window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-015"]={"FBXL5":{"hgnc":"HGNC:13602","symbol":"FBXL5","accessions":["Q9UKA1"],"name":"F-box/LRR-repeat protein 5","length":"691","function":"Component of some SCF (SKP1-cullin-F-box) protein ligase complex that plays a central role in iron homeostasis by promoting the ubiquitination and subsequent degradation of IREB2/IRP2 (PubMed:19762596, PubMed:19762597). The C-terminal domain of FBXL5 contains a redox-sensitive [2Fe-2S] cluster that, upon oxidation, promotes binding to IRP2 to effect its oxygen-dependent degradation (PubMed:32126207). Under iron deficiency conditions, the N-terminal hemerythrin-like (Hr) region, which contains a diiron metal center, cannot bind iron and undergoes conformational changes that destabilize the FBXL5 protein and cause its ubiquitination and degradation (PubMed:19762596, PubMed:19762597). When intracellular iron levels start rising, the Hr region is stabilized (PubMed:19762596, PubMed:19762597). Additional increases in iron levels facilitate the assembly and incorporation of a redox active [2Fe-2S] cluster in the C-terminal domain (PubMed:32126207). Only when oxygen level is high enough to maintain the cluster in its oxidized state can FBXL5 recruit IRP2 as a substrate for polyubiquitination and degradation (PubMed:32126207). Promotes ubiquitination and subsequent degradation of the dynactin complex component DCTN1 (PubMed:17532294). Within the nucleus, promotes the ubiquitination of SNAI1; preventing its interaction with DNA and promoting its degradation (PubMed:24157836). Negatively regulates DNA damage response by mediating the ubiquitin-proteasome degradation of the DNA repair protein NABP2 (PubMed:25249620)","subunit":"Part of a SCF (SKP1-cullin-F-box) protein ligase complex. Interacts with ACO1/IRP1, IREB2/IRP2; the interaction depends on the [2Fe-2S] cluster. Interacts with DCTN1/p150-glued","family":"","domains":[],"function_pmids":["17532294","19762596","19762597","32126207"],"location":"Cytoplasm, perinuclear region; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Component of some SCF (SKP1-cullin-F-box) protein ligase complex that plays a central role in iron homeostasis by promoting the ubiquitination and subsequent degradation of IREB2/IRP2 (PubMed:19762596, PubMed:19762597). The C-terminal domain of FBXL5 contains a redox-sensitive [2Fe-2S] cluster that, upon oxidation, promotes binding to IRP2 to effect its oxygen-dependent degradation (PubMed:32126207). Under iron deficiency conditions, the N-terminal hemerythrin-like (Hr) region, which contains a diiron metal center, cannot bind iron and undergoes conformational changes that destabilize the FBXL5 protein and cause its ubiquitination and degradation (PubMed:19762596, PubMed:19762597). When intracellular iron levels start rising, the Hr region is stabilized (PubMed:19762596, PubMed:19762597). Additional increases in iron levels facilitate the assembly and incorporation of a redox active [2Fe-2S] cluster in the C-terminal domain (PubMed:32126207). Only when oxygen level is high enough to maintain the cluster in its oxidized state can FBXL5 recruit IRP2 as a substrate for polyubiquitination and degradation (PubMed:32126207). Promotes ubiquitination and subsequent degradation of the dynactin complex component DCTN1 (PubMed:17532294). Within the nucleus, promotes the ubiquitination of SNAI1; preventing its interaction with DNA and promoting its degradation (PubMed:24157836). Negatively regulates DNA damage response by mediating the ubiquitin-proteasome degradation of the DNA repair protein NABP2 (PubMed:25249620)"},"FBXL6":{"hgnc":"HGNC:13603","symbol":"FBXL6","accessions":["Q8N531"],"name":"F-box/LRR-repeat protein 6","length":"539","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","subunit":"Directly interacts with SKP1 and CUL1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"FBXO10":{"hgnc":"HGNC:13589","symbol":"FBXO10","accessions":["Q9UK96"],"name":"F-box only protein 10","length":"956","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex. Mediates the ubiquitination and degradation of BCL2, an antiapoptotic protein, thereby playing a role in apoptosis by controlling the stability of BCL2. Targets also the receptor for advanced glycation end products RAGE for ubiquitination and subsequent lysosomal degradation (PubMed:28515150). Directly controls HGAL/GCSAM ubiquitination and degradation and thereby decreases BCR signaling (PubMed:31570756)","subunit":"Component of the SCF(FBXO10) complex consisting of CUL1, SKP1 and FBXO10 (PubMed:23431138). Interacts with BCL2 (PubMed:23431138). Interacts with PRDM1 (PubMed:24613396)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23431138","28515150","31570756"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"FBXO11":{"hgnc":"HGNC:13590","symbol":"FBXO11","accessions":["Q86XK2"],"name":"F-box only protein 11","length":"927","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins, such as DTL/CDT2, BCL6, SNAI1 and PRDM1/BLIMP1 (PubMed:17098746, PubMed:22113614, PubMed:23478441, PubMed:23478445, PubMed:23892434, PubMed:24613396, PubMed:24968003, PubMed:25827072, PubMed:29059170). The SCF(FBXO11) complex mediates ubiquitination and degradation of BCL6, thereby playing a role in the germinal center B-cells terminal differentiation toward memory B-cells and plasma cells (PubMed:22113614). The SCF(FBXO11) complex also mediates ubiquitination and degradation of DTL, an important step for the regulation of TGF-beta signaling, cell migration and the timing of the cell-cycle progression and exit (PubMed:23478441, PubMed:23478445). The SCF(FBXO11) complex also catalyzes ubiquitination and degradation of GSK3B-phosphorylated SNAI1 (PubMed:25827072, PubMed:29059170). Binds to and neddylates phosphorylated p53/TP53, inhibiting its transcriptional activity (PubMed:17098746). Plays a role in the regulatiom of erythropoiesis but not myelopoiesis or megakaryopoiesis (PubMed:33156908). Mechanistically, activates erythroid genes by mediating the degradation of BAHD1, a heterochromatin-associated protein that recruits corepressors to H3K27me3 marks (PubMed:33156908). Participates in macrophage cell death and inflammation in response to bacterial toxins by regulating the expression of complement 5a receptor 1/C5AR1 and IL-1beta (PubMed:33156908). Acts as a critical regulator to determine the level of MHC-II by mediating the recognition of degron at the P/S/T domain of CIITA leading to its ubiquitination and subsequent degradation via the proteasome (PubMed:37279268). Participates in the antiviral repsonse by initiating the activation of TBK1-IRF3-IFN-I axis (PubMed:36897010). Mediates the 'Lys-63'-linked ubiquitination of TRAF3 to strengthen the interaction between TRAF3 and TBK1 (PubMed:36897010)","subunit":"Component of the SCF(FBXO11) complex consisting of CUL1, RBX1, SKP1 and FBXO11 (PubMed:23478441, PubMed:23478445). Interacts with CIITA (PubMed:37279268)","family":"","domains":[],"function_pmids":["17098746","22113614","23478441","23478445","23892434","24613396","24968003","25827072","29059170","33156908","36897010","37279268"],"location":"Nucleus; Chromosome","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins, such as DTL/CDT2, BCL6, SNAI1 and PRDM1/BLIMP1 (PubMed:17098746, PubMed:22113614, PubMed:23478441, PubMed:23478445, PubMed:23892434, PubMed:24613396, PubMed:24968003, PubMed:25827072, PubMed:29059170). The SCF(FBXO11) complex mediates ubiquitination and degradation of BCL6, thereby playing a role in the germinal center B-cells terminal differentiation toward memory B-cells and plasma cells (PubMed:22113614). The SCF(FBXO11) complex also mediates ubiquitination and degradation of DTL, an important step for the regulation of TGF-beta signaling, cell migration and the timing of the cell-cycle progression and exit (PubMed:23478441, PubMed:23478445). The SCF(FBXO11) complex also catalyzes ubiquitination and degradation of GSK3B-phosphorylated SNAI1 (PubMed:25827072, PubMed:29059170). Binds to and neddylates phosphorylated p53/TP53, inhibiting its transcriptional activity (PubMed:17098746). Plays a role in the regulatiom of erythropoiesis but not myelopoiesis or megakaryopoiesis (PubMed:33156908). Mechanistically, activates erythroid genes by mediating the degradation of BAHD1, a heterochromatin-associated protein that recruits corepressors to H3K27me3 marks (PubMed:33156908). Participates in macrophage cell death and inflammation in response to bacterial toxins by regulating the expression of complement 5a receptor 1/C5AR1 and IL-1beta (PubMed:33156908). Acts as a critical regulator to determine the level of MHC-II by mediating the recognition of degron at the P/S/T domain of CIITA leading to its ubiquitination and subsequent degradation via the proteasome (PubMed:37279268). Participates in the antiviral repsonse by initiating the activation of TBK1-IRF3-IFN-I axis (PubMed:36897010). Mediates the 'Lys-63'-linked ubiquitination of TRAF3 to strengthen the interaction between TRAF3 and TBK1 (PubMed:36897010)"},"FBXO17":{"hgnc":"HGNC:18754","symbol":"FBXO17","accessions":["Q96EF6"],"name":"F-box only protein 17","length":"278","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex. Able to recognize and bind denatured glycoproteins, which are modified with complex-type oligosaccharides. Also recognizes sulfated glycans. Does not bind high-mannose glycoproteins","subunit":"Part of a SCF (SKP1-cullin-F-box) protein ligase complex. Interacts with SKP1 and CUL1","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex. Able to recognize and bind denatured glycoproteins, which are modified with complex-type oligosaccharides. Also recognizes sulfated glycans. Does not bind high-mannose glycoproteins"},"FBXO2":{"hgnc":"HGNC:13581","symbol":"FBXO2","accessions":["Q9UK22"],"name":"F-box only protein 2","length":"296","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex that mediates the ubiquitination and subsequent proteasomal degradation of target proteins. Involved in the endoplasmic reticulum-associated degradation pathway (ERAD) for misfolded lumenal proteins by recognizing and binding sugar chains on unfolded glycoproteins that are retrotranslocated into the cytosol and promoting their ubiquitination and subsequent degradation. Prevents formation of cytosolic aggregates of unfolded glycoproteins that have been retrotranslocated into the cytosol. Able to recognize and bind denatured glycoproteins, preferentially those of the high-mannose type (By similarity)","subunit":"Component of the SCF(FBXO2) complex consisting of CUL1, RBX1, SKP1 and FBXO2. Predominantly detected as heterodimer with SKP1; the heterodimer with SKP1 is not part of the SCF(FBXO2) complex (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Microsome membrane；Peripheral membrane protein；Cytoplasmic side","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex that mediates the ubiquitination and subsequent proteasomal degradation of target proteins.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"FBXO21":{"hgnc":"HGNC:13592","symbol":"FBXO21","accessions":["O94952"],"name":"F-box only protein 21","length":"628","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","subunit":"Directly interacts with SKP1 and CUL1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"FBXO22":{"hgnc":"HGNC:13593","symbol":"FBXO22","accessions":["Q8NEZ5"],"name":"F-box only protein 22","length":"403","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex that is implicated in the control of various cellular processes such as cell cycle control, transcriptional regulation, DNA damage repair, and apoptosis. Promotes the proteasome-dependent degradation of key sarcomeric proteins, such as alpha-actinin (ACTN2) and filamin-C (FLNC), essential for maintenance of normal contractile function. Acts as a key regulator of histone methylation marks namely H3K9 and H3K36 methylation through the regulation of histone demethylase KDM4A protein levels (PubMed:21768309). In complex with KDM4A, also regulates the abundance of TP53 by targeting methylated TP53 for degradation at the late senescent stage (PubMed:26868148). Under oxidative stress, promotes the ubiquitination and degradation of BACH1. Mechanistically, reactive oxygen species (ROS) covalently modify cysteine residues on the bZIP domain of BACH1, leading to its release from chromatin and making it accessible to FBXO22 (PubMed:39504958). Upon amino acid depletion, mediates 'Lys-27'-linked ubiquitination of MTOR and thereby inhibits substrate recruitment to mTORC1 (PubMed:37979583). Also inhibits SARS-CoV-2 replication by inducing NSP5 degradation (PubMed:39223933)","subunit":"Directly interacts with SKP1 and CUL1 (PubMed:21768309, PubMed:22972877). Interacts (via C-terminal) with KDM4A (PubMed:21768309). Interacts with TP53 (PubMed:26868148). Interacts with MTOR; this interaction promotes 'lys-27'-linked ubiquitination of MTOR (PubMed:37979583)\n(Microbial infection) Interacts with SARS_COV-2 protein NSP5; this interaction attenuates NSP5-mediated inhibition of innate immunity","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21768309","22972877","26868148","37979583","39223933","39504958"],"location":"Cytoplasm；Nucleus；Cytoplasm, myofibril, sarcomere, Z line","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex that is implicated in the control of various cellular processes such as cell cycle control, transcriptional regulation, DNA damage repair, and apoptosis.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡"},"FBXO25":{"hgnc":"HGNC:13596","symbol":"FBXO25","accessions":["Q8TCJ0"],"name":"F-box only protein 25","length":"367","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex. May play a role in accumulation of expanded polyglutamine (polyQ) protein huntingtin (HTT) (By similarity)","subunit":"Part of a SCF (SKP1-cullin-F-box) protein ligase complex consisting of FBXO25, SKP1, CUL1 and RBX1. Interacts directly with SKP1 and CUL1. Interacts (via C-terminus) with beta-actin (via N-terminus)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"FBXO28":{"hgnc":"HGNC:29046","symbol":"FBXO28","accessions":["Q9NVF7"],"name":"F-box only protein 28","length":"368","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex, promoting ubiquitination and proteasomal degradation of specific target proteins including TOP2A, RAB27A or itself (PubMed:27754753, PubMed:31678254). Regulates topoisomerase IIalpha/TOP2A decatenation activity and plays an important role in maintaining genomic stability (PubMed:27754753). Plays a role in lipid metabolism and inflammation through the ubiquitinated degradation of RAB27A (By similarity). Strongly regulates beta-cell survival without having any significant independent effect on insulin secretion (PubMed:29587369). Plays an essential role in spindle morphology and actin-based spindle migration probably through the ARPC2/ARP3 signaling pathway (By similarity)","subunit":"Part of a SCF (SKP1-cullin-F-box) protein ligase complex","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["27754753","29587369","31678254"],"location":"Chromosome, centromere, kinetochore；Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex, promoting ubiquitination and proteasomal degradation of specific target proteins including TOP2A, RAB27A or itself (PubMed:27754753, PubMed:31678254).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢"},"FBXO32":{"hgnc":"HGNC:16731","symbol":"FBXO32","accessions":["Q969P5"],"name":"F-box only protein 32","length":"355","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins. Probably recognizes and binds to phosphorylated target proteins during skeletal muscle atrophy. Recognizes TERF1. Negatively regulates macrophage efferocytosis by promoting the ubiquitination of the transcription factor KLF4, suppressing the receptor tyrosine kinase MERTK transcription (By similarity). Regulates LPS-induced apoptosis and mitochondrial dysfunction through ANXA1 ubiquitination and degradation (By similarity). Mediates cyclin D1 protein stabilization via 'Lys-27'-linked ubiquitination (PubMed:40307251)","subunit":"Part of the SCF (SKP1-CUL1-F-box) E3 ubiquitin-protein ligase complex SCF(FBXO32) formed of CUL1, SKP1, RBX1 and FBXO32. Interacts with cyclin D1/CCND1 (PubMed:40307251)","family":"","domains":[],"function_pmids":["15531760","40307251"],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins. Probably recognizes and binds to phosphorylated target proteins during skeletal muscle atrophy. Recognizes TERF1. Negatively regulates macrophage efferocytosis by promoting the ubiquitination of the transcription factor KLF4, suppressing the receptor tyrosine kinase MERTK transcription (By similarity). Regulates LPS-induced apoptosis and mitochondrial dysfunction through ANXA1 ubiquitination and degradation (By similarity). Mediates cyclin D1 protein stabilization via 'Lys-27'-linked ubiquitination (PubMed:40307251)"},"FBXO38":{"hgnc":"HGNC:28844","symbol":"FBXO38","accessions":["Q6PIJ6"],"name":"F-box only protein 38","length":"1188","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of PDCD1/PD-1, thereby regulating T-cells-mediated immunity (PubMed:30487606). Required for anti-tumor activity of T-cells by promoting the degradation of PDCD1/PD-1; the PDCD1-mediated inhibitory pathway being exploited by tumors to attenuate anti-tumor immunity and facilitate tumor survival (PubMed:30487606). May indirectly stimulate the activity of transcription factor KLF7, a regulator of neuronal differentiation, without promoting KLF7 ubiquitination (By similarity)","subunit":"Part of the SCF (SKP1-CUL1-F-box) E3 ubiquitin-protein ligase complex SCF(FBXO38) composed of CUL1, SKP1, RBX1 and FBXO38 (Probable). Interacts with KLF7 (By similarity). Interacts with PDCD1/PD-1 (PubMed:30487606)","family":"","domains":[],"function_pmids":["30487606"],"location":"Cytoplasm, cytosol; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of PDCD1/PD-1, thereby regulating T-cells-mediated immunity (PubMed:30487606). Required for anti-tumor activity of T-cells by promoting the degradation of PDCD1/PD-1; the PDCD1-mediated inhibitory pathway being exploited by tumors to attenuate anti-tumor immunity and facilitate tumor survival (PubMed:30487606). May indirectly stimulate the activity of transcription factor KLF7, a regulator of neuronal differentiation, without promoting KLF7 ubiquitination (By similarity)"},"FBXO42":{"hgnc":"HGNC:29249","symbol":"FBXO42","accessions":["Q6P3S6"],"name":"F-box only protein 42","length":"717","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex. Required for bipolar spindle formation during mitosis (PubMed:33539788). Recognizes p53/TP53 phosphorylated by CSN-associated kinase, promoting its polyubiquitination and proteasomal degradation (PubMed:19509332, PubMed:21127074, PubMed:39134694). Positively regulates the Notch signaling pathway through 'Lys-63'-linked polyubiquitination of the transcriptional effector RBPJ, stabilizing its chromatin association and potentiating transcriptional activation of Notch target genes (PubMed:36129980). Mediates 'Lys-48'-linked polyubiquitination and proteasomal degradation of components of the PP4 phosphatase complex, including PP4C, PP4R2, PP4R3A and PP4R3B, thereby restraining PP4 phosphatase activity and ensuring proper DNA damage response signaling (PubMed:41484364). Collaborates with CCDC6 to promote polyubiquitination and proteasomal degradation of the catalytic subunit PP2AC (PubMed:41986709). Recognizes ACAA2, promoting its ubiquitination and proteasomal degradation in hepatocytes, thereby attenuating fatty acid beta-oxidation; this activity is negatively regulated by CAND1, which prevents assembly of the SCF(FBXO42)-ACAA2 degradation complex (By similarity)","subunit":"Component of some SCF complex, composed of CUL1, SKP1, RBX1 and FBXO42. Interacts (via the kelch domain) with p53/TP53; interaction is direct (PubMed:21127074). Interacts with RBPJ (PubMed:36129980). Interacts with PP4 including components PP4C, PP4R1, PP4R2, PP4R3A and PP4R3B (PubMed:41484364). Interacts with CCDC6 (PubMed:41484364, PubMed:41986709). Interacts with PPP2CA (PubMed:41986709)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19509332","21127074","33539788","36129980","39134694","41484364","41986709"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号"},"FBXO45":{"hgnc":"HGNC:29148","symbol":"FBXO45","accessions":["P0C2W1"],"name":"F-box/SPRY domain-containing protein 1","length":"286","function":"Component of E3 ubiquitin ligase complex consisting of FBXO45, MYCBP2 and SKP1 (PubMed:29997255). Functions in substrate recognition but also plays an important role in assembly of the complex (PubMed:29997255). Required for normal neuromuscular synaptogenesis, axon pathfinding and neuronal migration (By similarity). Regulates neuron migration during brain development through interaction with N-cadherin/CDH2 after secretion via a non-classical mechanism (By similarity). Plays a role in the regulation of neurotransmission at mature neurons (By similarity). May control synaptic activity by controlling UNC13A via ubiquitin dependent pathway (By similarity). Specifically recognizes TP73, promoting its ubiquitination and degradation. Polyubiquitinates NMNAT2, an adenylyltransferase that acts as an axon maintenance factor, and regulates its stability and degradation by the proteasome (PubMed:29997255). Also acts by ubiquitinating FBXW7 during prolonged mitotic arrest and promotes FBXW7 proteasomal degradation (PubMed:31285543). Induces subsequently an increase in mitotic slippage and prevents mitotic cell death (PubMed:31285543). In response to influenza infection, mediates interferon-lambda receptor IFNLR1 polyubiquitination and degradation through the ubiquitin-proteasome system by docking with its intracellular receptor domain (PubMed:36379255)","subunit":"Forms a complex with MYCBP2 and SKP1 (PubMed:29997255). Interacts with HEY1; leading to FBXO45 nuclear translocation. Interacts (via SPRY domain) with CDH2 (PubMed:32341084)","family":"Belongs to the FBXO45/Fsn family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19581926","29997255","31285543","36379255"],"location":"Secreted；Postsynaptic cell membrane；Presynaptic cell membrane；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Component of E3 ubiquitin ligase complex consisting of FBXO45, MYCBP2 and SKP1 (PubMed:29997255).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"FBXO48":{"hgnc":"HGNC:33857","symbol":"FBXO48","accessions":["Q5FWF7"],"name":"F-box only protein 48","length":"155","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 32-79: F-box [ECO:0000255/PROSITE-ProRule/PRU00080]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FBXO6":{"hgnc":"HGNC:13585","symbol":"FBXO6","accessions":["Q9NRD1"],"name":"F-box only protein 6","length":"293","function":"Substrate-recognition component of some SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complexes. Involved in endoplasmic reticulum-associated degradation pathway (ERAD) for misfolded lumenal proteins by recognizing and binding sugar chains on unfolded glycoproteins that are retrotranslocated into the cytosol and promoting their ubiquitination and subsequent degradation. Able to recognize and bind denatured glycoproteins, which are modified with not only high-mannose but also complex-type oligosaccharides. Also recognizes sulfated glycans. Also involved in DNA damage response by specifically recognizing activated CHEK1 (phosphorylated on 'Ser-345'), promoting its ubiquitination and degradation. Ubiquitination of CHEK1 is required to ensure that activated CHEK1 does not accumulate as cells progress through S phase, or when replication forks encounter transient impediments during normal DNA replication","subunit":"Interacts with VCP (By similarity). Part of a SCF (SKP1-cullin-F-box) protein ligase complex. Interacts with CHEK1 and CUL1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18203720","19716789"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；激酶/磷酸化信号；注释原文：Substrate-recognition component of some SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complexes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；激酶/磷酸化信号"},"FBXO7":{"hgnc":"HGNC:13586","symbol":"FBXO7","accessions":["Q9Y3I1"],"name":"F-box only protein 7","length":"522","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins and plays a role in several biological processes such as cell cycle, cell proliferation, or maintenance of chromosome stability (PubMed:15145941, PubMed:34791250). Recognizes and ubiquitinates BIRC2 and the cell cycle regulator DLGAP5 (PubMed:15145941, PubMed:16510124, PubMed:22212761). Plays a role downstream of PINK1 in the clearance of damaged mitochondria via selective autophagy (mitophagy) by targeting PRKN to dysfunctional depolarized mitochondria. Promotes MFN1 ubiquitination. Mediates the ubiquitination and proteasomal degradation of UXT isoform 2, thereby impairing the NF-kappa-B signaling pathway (PubMed:33010352). Inhibits NF-kappa-B pathway also by promoting the ubiquitination of TRAF2 (PubMed:22212761). Affects the assembly state and activity of the proteasome in the cells including neurons by ubiquitinating the proteasomal subunit PSMA2 via 'Lys-63'-linked polyubiquitin chains (By similarity). Promotes 'Lys-48'-linked polyubiquitination SIRT7, leading to the hydrogen peroxide-induced cell death (PubMed:36646384)","subunit":"Part of the SCF (SKP1-CUL1-F-box) E3 ubiquitin-protein ligase complex SCF(FBXO7) formed of CUL1, SKP1, RBX1 and FBXO7. Interacts via its C-terminal proline-rich region with DLGAP5. Interacts with BIRC2. Interacts with CDK6 and promotes its interaction with D-type cyclin. Interacts with PSMF1\nInteracts (via the N-terminal Ubl domain) with PRKN (PubMed:23933751). Interact (via N-terminal region) with PINK1 (PubMed:23933751)\nInteract (via N-terminal region) with PINK1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15145941","16510124","22212761","23933751","33010352","34791250","36646384"],"location":"Cytoplasm；Nucleus；Mitochondrion；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins and plays a role in several biological processes such as cell cycle, cell proliferation, or maintenance of chromosome stability (PubMed:15145941, PubMed:34791250).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢"},"FBXW10":{"symbol":"FBXW10","accessions":["Q5XX13"],"name":"F-box/WD repeat-containing protein 10","length":1052,"function":"Probable substrate-recognition component of a SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins. Overexpression is leading to degradati...","subunit":"无可用SUBUNIT段","domains":"Repeat: WD 1 [169–206]\nDomain: F-box [276–323]\nRepeat: WD 2 [409–447]\nRepeat: WD 3 [451–490]\nRepeat: WD 4 [493–532]\nRepeat: WD 5 [534–569]\nRepeat: WD 6 [572–609]\nRepeat: WD 7 [611–652]","brief":"泛素化/蛋白稳态；注释原文：Probable substrate-recognition component of a SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态","location":"当前记录无定位注释","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"FBXW10B":{"hgnc":"HGNC:14379","symbol":"FBXW10B","accessions":["O95170"],"name":"F-box and WD repeat domain containing protein 10B","length":"752","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Repeat 169-206: WD 1 [ECO:0000255]\nRepeat 451-490: WD 2 [ECO:0000255]\nRepeat 493-532: WD 3 [ECO:0000255]\nRepeat 534-569: WD 4 [ECO:0000255]\nRepeat 572-609: WD 5 [ECO:0000255]\nRepeat 611-652: WD 6 [ECO:0000255]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FBXW11":{"hgnc":"HGNC:13607","symbol":"FBXW11","accessions":["Q9UKB1"],"name":"F-box/WD repeat-containing protein 11","length":"542","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:10437795, PubMed:10648623, PubMed:11158290, PubMed:19966869, PubMed:20347421, PubMed:22017875, PubMed:22017876, PubMed:36608670). Probably recognizes and binds to phosphorylated target proteins: the interaction with substrates requires the phosphorylation of the two serine residues in the substrates' destruction motif D-S-G-X(2,3,4)-S (PubMed:10437795, PubMed:10648623, PubMed:19966869, PubMed:20347421, PubMed:22017875, PubMed:22017876, PubMed:36608670). SCF(FBXW11) mediates the ubiquitination of phosphorylated CTNNB1 and participates in Wnt signaling regulation (PubMed:10321728). SCF(FBXW11) plays a key role in NF-kappa-B activation by mediating ubiquitination of phosphorylated NFKBIA, leading to its degradation by the proteasome, thereby allowing the associated NF-kappa-B complex to translocate into the nucleus and to activate transcription (PubMed:10321728, PubMed:10437795, PubMed:10644755, PubMed:20347421). The SCF(FBXW11) complex also regulates NF-kappa-B by mediating ubiquitination of phosphorylated NFKB1: specifically ubiquitinates the p105 form of NFKB1, leading to its degradation (PubMed:11158290). SCF(FBXW11) mediates the ubiquitination of IFNAR1 (PubMed:14532120, PubMed:15337770). SCF(FBXW11) mediates the ubiquitination of CEP68; this is required for centriole separation during mitosis (PubMed:25503564). Involved in the oxidative stress-induced a ubiquitin-mediated decrease in RCAN1 (PubMed:18575781). Mediates the degradation of CDC25A induced by ionizing radiation in cells progressing through S phase and thus may function in the intra-S-phase checkpoint (PubMed:14603323). Has an essential role in the control of the clock-dependent transcription via degradation of phosphorylated PER1 and phosphorylated PER2 (PubMed:15917222). SCF(FBXW11) mediates the ubiquitination of CYTH1, and probably CYTH2 (PubMed:29420262). SCF(FBXW11) acts as a regulator of mTORC1 signaling pathway by catalyzing ubiquitination and subsequent proteasomal degradation of phosphorylated DEPTOR, TFE3 and MITF (PubMed:22017875, PubMed:22017876, PubMed:36608670)\n(Microbial infection) Target of human immunodeficiency virus type 1 (HIV-1) protein VPU to polyubiquitinate and deplete BST2 from cells and antagonize its antiviral action","subunit":"Self-associates (PubMed:10644755). Component of the SCF(FBXW11) complex formed of CUL1, SKP1, RBX1 and a FBXW11 dimer (PubMed:10066435, PubMed:10437795, PubMed:20347421, PubMed:22017875, PubMed:22017876, PubMed:36608670). Interacts with BST2 and USP47 (PubMed:19730691, PubMed:19966869). Interacts with TRIM21 (PubMed:16880511). Interacts with PER3 (PubMed:15917222). Interacts with INAVA (PubMed:29420262). Interacts with REST (PubMed:18354482)\n(Microbial infection) Interact with Rift valley fever virus NSs (via omegaXaV motif); this interaction is important for EIF2AK2/PKR degradation","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10321728","10437795","10644755","10648623","11158290","14532120","14603323","15337770","15917222","18575781","19730691","19966869","20347421","22017875","22017876","25503564","29420262","36608670"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；注释原文：Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:10437795, PubMed:10648623, PubMed:11158290, PubMed:19966869, PubMed:20347421, PubMed:22017875, PubMed:22017876, PubMed:36608670).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡"},"FBXW2":{"hgnc":"HGNC:13608","symbol":"FBXW2","accessions":["Q9UKT8"],"name":"F-box/WD repeat-containing protein 2","length":"454","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","subunit":"Directly interacts with SKP1 and CUL1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","function_evidence":"数据库整理/推断；按原文限定；","categories":"泛素化/蛋白稳态"},"FBXW4":{"hgnc":"HGNC:10847","symbol":"FBXW4","accessions":["P57775"],"name":"F-box/WD repeat-containing protein 4","length":"412","function":"Probably recognizes and binds to some phosphorylated proteins and promotes their ubiquitination and degradation. Likely to be involved in key signaling pathways crucial for normal limb development. May participate in Wnt signaling","subunit":"Part of a SCF (SKP1-cullin-F-box) protein ligase complex (Probable). Interacts with POUF51 (By similarity)","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Probably recognizes and binds to some phosphorylated proteins and promotes their ubiquitination and degradation. Likely to be involved in key signaling pathways crucial for normal limb development. May participate in Wnt signaling"},"FBXW5":{"hgnc":"HGNC:13613","symbol":"FBXW5","accessions":["Q969U6"],"name":"F-box/WD repeat-containing protein 5","length":"566","function":"Substrate recognition component of both SCF (SKP1-CUL1-F-box protein) and DCX (DDB1-CUL4-X-box) E3 ubiquitin-protein ligase complexes. Substrate recognition component of the SCF(FBXW5) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of SASS6 during S phase, leading to prevent centriole reduplication. The SCF(FBXW5) complex also mediates ubiquitination and degradation of actin-regulator EPS8 during G2 phase, leading to the transient degradation of EPS8 and subsequent cell shape changes required to allow mitotic progression. Substrate-specific adapter of the DCX(FBXW5) E3 ubiquitin-protein ligase complex which mediates the polyubiquitination and subsequent degradation of TSC2. May also act as a negative regulator of MAP3K7/TAK1 signaling in the interleukin-1B (IL1B) signaling pathway","subunit":"Part of the SCF (SKP1-CUL1-F-box) E3 ubiquitin-protein ligase complex SCF(FBXW5) composed of CUL1, SKP1, RBX1 and FBXW5. Component of the DCX(FBXW5) E3 ubiquitin ligase complex, at least composed of (CUL4A or CUL4B), DDB1, FBXW5 and RBX1. Interacts with CDC20, EPS8, TSC1, TSC2 and SASS6. Interacts with TNFAIP8L1; TNFAIP8L1 competes with TSC2 to bind FBXW5 increasing TSC2 stability by preventing its ubiquitination","family":"Belongs to the FBXW5 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18381890","19232515","21725316"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛；注释原文：Substrate recognition component of both SCF (SKP1-CUL1-F-box protein) and DCX (DDB1-CUL4-X-box) E3 ubiquitin-protein ligase complexes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛"},"FBXW7":{"hgnc":"HGNC:16712","symbol":"FBXW7","accessions":["Q969H0"],"name":"F-box/WD repeat-containing protein 7","length":"707","function":"Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:17434132, PubMed:22748924, PubMed:26976582, PubMed:28727686, PubMed:34741373, PubMed:35395208). Recognizes and binds phosphorylated sites/phosphodegrons within target proteins and thereafter brings them to the SCF complex for ubiquitination (PubMed:17434132, PubMed:22748924, PubMed:26774286, PubMed:26976582, PubMed:28727686, PubMed:34741373). Identified substrates include cyclin-E (CCNE1 or CCNE2), DISC1, JUN, MYC, NOTCH1 released notch intracellular domain (NICD), NFE2L1, NOTCH2, MCL1, MLST8, RICTOR, and probably PSEN1 (PubMed:11565034, PubMed:11585921, PubMed:12354302, PubMed:14739463, PubMed:15103331, PubMed:17558397, PubMed:17873522, PubMed:22608923, PubMed:22748924, PubMed:25775507, PubMed:25897075, PubMed:26976582, PubMed:28007894, PubMed:28727686, PubMed:29149593, PubMed:34102342). Acts as a negative regulator of JNK signaling by binding to phosphorylated JUN and promoting its ubiquitination and subsequent degradation (PubMed:14739463). Involved in bone homeostasis and negative regulation of osteoclast differentiation (PubMed:29149593). Regulates the amplitude of the cyclic expression of hepatic core clock genes and genes involved in lipid and glucose metabolism via ubiquitination and proteasomal degradation of their transcriptional repressor NR1D1; CDK1-dependent phosphorylation of NR1D1 is necessary for SCF(FBXW7)-mediated ubiquitination (PubMed:27238018). Also able to promote 'Lys-63'-linked ubiquitination in response to DNA damage (PubMed:26774286). The SCF(FBXW7) complex facilitates double-strand break repair following phosphorylation by ATM: phosphorylation promotes localization to sites of double-strand breaks and 'Lys-63'-linked ubiquitination of phosphorylated XRCC4, enhancing DNA non-homologous end joining (PubMed:26774286)","subunit":"Homodimer; homodimerization plays a role in substrate binding and/or ubiquitination and degradation (PubMed:17434132, PubMed:22608923, PubMed:28007894). Component of the SCF(FBXW7) complex consisting of CUL1, RBX1, SKP1 and FBXW7 (PubMed:11565034, PubMed:15103331, PubMed:22748924, PubMed:26774286, PubMed:26976582, PubMed:28007894, PubMed:28727686, PubMed:34741373). Interacts (via F-box domain) with SKP1 (PubMed:11585921, PubMed:17434132, PubMed:26976582, PubMed:28007894, PubMed:28727686). Interacts (via F-box domain) with pseudophosphatase STYX; the interaction is direct and prevents FBXW7 interaction with SKP1 (PubMed:28007894). Interacts with cyclin-E (CCNE1 or CCNE2) (PubMed:11565034, PubMed:17434132). Interacts with PSEN1 (PubMed:12354302). Forms a trimeric complex with NOTCH1 and SGK1 (PubMed:21147854). Interacts with NOTCH1 intracellular domain/NICD and NOTCH4 intracellular domain/NICD (PubMed:11585921). Interacts with NOTCH2 intracellular domain (N2ICD) (PubMed:29149593). Interacts with MYC (when phosphorylated) (PubMed:17873522, PubMed:25775507, PubMed:28007894). Interacts with USP28, counteracting ubiquitination of MYC (PubMed:17873522). Interacts with JUN (PubMed:14739463, PubMed:22608923). Found in a complex with JUN and PRR7 (PubMed:27458189). Interacts with JUN and PRR7; the interaction inhibits ubiquitination-mediated JUN degradation, promoting its phosphorylation and transcriptional activity (PubMed:27458189). Interacts (when phosphorylated at Thr-205) with PIN1, disrupting FBXW7 dimerization and promoting FBXW7 autoubiquitination and degradation (PubMed:22608923). Interacts with UBE2QL1 (PubMed:24000165). Interacts with FAM83D; promotes FBXW7 degradation (PubMed:24344117). Interacts with MYCN; FBXW7 competes with AURKA for binding to unphosphorylated MYCN but not for binding to phosphorylated MYCN (PubMed:27837025). Interacts with STOML1 (PubMed:23082202). Interacts with NFE2L1 (By similarity). Interacts with USP36, counteracting ubiquitination of MYC (PubMed:25775507). Interacts with NR1D1 (PubMed:27238018). Interacts with RICTOR; mediates RICTOR ubiquitination and degradation (PubMed:25897075). Interacts with USP38, counteracting ubiquitination of MYC (PubMed:34102342)\n(Microbial infection) Interacts (via WD repeats) with SV40 large T antigen (via CPD region)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11565034","11585921","12354302","14739463","15103331","17434132","17558397","17873522","22608923","22748924","25775507","25897075","26774286","26976582","27238018","28007894","28727686","29149593","34102342","34741373","35395208"],"location":"Nucleus, nucleoplasm；Chromosome；Cytoplasm；Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；线粒体/代谢；发育/分化；注释原文：Substrate recognition component of a SCF (SKP1-CUL1-F-box protein) E3 ubiquitin-protein ligase complex which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:17434132, PubMed:22748924, PubMed:26976582, PubMed:28727686, PubMed:34741373, PubMed:35395208).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；线粒体/代谢；发育/分化"},"FBXW8":{"hgnc":"HGNC:13597","symbol":"FBXW8","accessions":["Q8N3Y1"],"name":"F-box/WD repeat-containing protein 8","length":"598","function":"Substrate-recognition component of the Cul7-RING(FBXW8) ubiquitin ligase complex, which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:17205132, PubMed:18498745, PubMed:21572988, PubMed:24362026, PubMed:35982156). The Cul7-RING(FBXW8) complex mediates ubiquitination and consequent degradation of GORASP1, acting as a component of the ubiquitin ligase pathway that regulates Golgi morphogenesis and dendrite patterning in brain (PubMed:21572988). Mediates ubiquitination and degradation of IRS1 in a mTOR-dependent manner: the Cul7-RING(FBXW8) complex recognizes and binds IRS1 previously phosphorylated by S6 kinase (RPS6KB1 or RPS6KB2) (PubMed:18498745). The Cul7-RING(FBXW8) complex also mediates ubiquitination of MAP4K1/HPK1: recognizes and binds autophosphorylated MAP4K1/HPK1, leading to its degradation, thereby affecting cell proliferation and differentiation (PubMed:24362026). The Cul7-RING(FBXW8) complex also mediates ubiquitination of phosphorylated cyclin-D1 (CCND1) (PubMed:17205132). The Cul7-RING(FBXW8) complex is however not a major regulator of CCND1 stability during the G1/S transition (By similarity). Associated component of the 3M complex, suggesting that it mediates some of 3M complex functions (PubMed:24793695)","subunit":"Component of the Cul7-RING(FBXW8) complex consisting of CUL7, RBX1, SKP1 and FBXW8; within the complex interacts with CUL7 and SKP1 (PubMed:12904573, PubMed:17205132, PubMed:17332328, PubMed:21572988, PubMed:24362026, PubMed:35982156). Interacts with GLMN isoform 1 (PubMed:12904573). Interacts with OBSL1, CUL1, CUL2, CCT6B, PFDN5, CCT2, CCT3, CCT6A, CCT7, VBP1, CCDC8, ARF1, TRIP13, PDCD5 and GORASP1 (PubMed:21572988). Interacts with MAP4K1/HPK1 (when autophosphorylated) (PubMed:24362026). Associated component of the 3M complex (PubMed:24793695, PubMed:35982156). Interacts with POUF51 (when phosphorylated on 'Ser-355') (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17205132","18498745","21572988","24362026","24793695","35982156"],"location":"Cytoplasm, perinuclear region；Golgi apparatus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；发育/分化；注释原文：Substrate-recognition component of the Cul7-RING(FBXW8) ubiquitin ligase complex, which mediates the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:17205132, PubMed:18498745, PubMed:21572988, PubMed:24362026, PubMed:35982156).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；发育/分化"},"FBXW9":{"hgnc":"HGNC:28136","symbol":"FBXW9","accessions":["Q5XUX1"],"name":"F-box/WD repeat-containing protein 9","length":"458","function":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex","subunit":"Interacts with SKP1 and CUL1","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate-recognition component of the SCF (SKP1-CUL1-F-box protein)-type E3 ubiquitin ligase complex"},"FCF1":{"hgnc":"HGNC:20220","symbol":"FCF1","accessions":["Q9Y324"],"name":"rRNA-processing protein FCF1 homolog","length":"198","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"Belongs to the UTP23/FCF1 family. FCF1 subfamily","domains":[],"function_pmids":["34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome"},"FCHO1":{"hgnc":"HGNC:29002","symbol":"FCHO1","accessions":["O14526"],"name":"F-BAR domain only protein 1","length":"889","function":"Functions in an early step of clathrin-mediated endocytosis (PubMed:30822429). Has both a membrane binding/bending activity and the ability to recruit proteins essential to the formation of functional clathrin-coated pits. May regulate Bmp signaling by regulating clathrin-mediated endocytosis of Bmp receptors. Involved in the regulation of T-cell proliferation and activation (PubMed:30822429, PubMed:32098969). Affects TCR clustering upon receptor triggering and modulates its internalization, playing a role in TCR-dependent T-cell activation (PubMed:32098969)","subunit":"May oligomerize and form homotetramer (By similarity). Interacts with AP2A2 and AP2B1; 2 subunits of the adaptor protein complex AP-2 (By similarity). Interacts with DAB2. Interacts with clathrin (CLTC or CLTCL1). Interacts with EPS15, EPS15R and ITSN1. Interacts with AGFG1 and CALM. May interact with ACVR1; linking this receptor to clathrin-mediated endocytosis (PubMed:22484487)","family":"Belongs to the FCHO family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20448150","30822429","32098969"],"location":"Membrane, clathrin-coated pit；Peripheral membrane protein；Cytoplasmic side","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：Functions in an early step of clathrin-mediated endocytosis (PubMed:30822429).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；黏附/受体/细胞表面"},"FCHSD2":{"hgnc":"HGNC:29114","symbol":"FCHSD2","accessions":["O94868"],"name":"F-BAR and double SH3 domains protein 2","length":"740","function":"Adapter protein that plays a role in endocytosis via clathrin-coated pits. Contributes to the internalization of cell surface receptors, such as integrin ITGB1 and transferrin receptor (PubMed:29887380). Promotes endocytosis of EGFR in cancer cells, and thereby contributes to the down-regulation of EGFR signaling (PubMed:30249660). Recruited to clathrin-coated pits during a mid-to-late stage of assembly, where it is required for normal progress from U-shaped intermediate stage pits to terminal, omega-shaped pits (PubMed:29887380). Binds to membranes enriched in phosphatidylinositol 3,4-bisphosphate or phosphatidylinositol 3,4,5-trisphosphate (PubMed:29887380). When bound to membranes, promotes actin polymerization via its interaction with WAS and/or WASL which leads to the activation of the Arp2/3 complex. Does not promote actin polymerization in the absence of membranes (PubMed:29887380)","subunit":"Homodimer (PubMed:29887380). Interacts (via SH3 domain 2) with ITSN1 (via SH3 domain 4). Recruited to clathrin-coated pits during a mid-to-late stage of assembly via interaction with ITSN1. Interacts (via SH3 domain 1) with WASL (PubMed:29887380). Interacts with WAS (By similarity). Interacts with CASK and MAGI1. CASK inhibits interaction with MAGI1 (PubMed:14627983)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29887380","30249660"],"location":"Cytoplasm；Cell junction；Membrane, clathrin-coated pit；Cell membrane；Peripheral membrane protein；Cytoplasmic side；Cell projection, stereocilium","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：Adapter protein that plays a role in endocytosis via clathrin-coated pits.","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛；黏附/受体/细胞表面"},"FDXACB1":{"hgnc":"HGNC:25110","symbol":"FDXACB1","accessions":["Q9BRP7"],"name":"Ferredoxin-fold anticodon-binding domain-containing protein 1","length":"624","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 531-624: FDX-ACB [ECO:0000255/PROSITE-ProRule/PRU00778]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FEM1A":{"hgnc":"HGNC:16934","symbol":"FEM1A","accessions":["Q9BSK4"],"name":"Protein fem-1 homolog A","length":"669","function":"Substrate-recognition component of a Cul2-RING (CRL2) E3 ubiquitin-protein ligase complex of the DesCEND (destruction via C-end degrons) pathway, which recognizes a C-degron located at the extreme C terminus of target proteins, leading to their ubiquitination and degradation (PubMed:29779948, PubMed:33398168, PubMed:33398170). The C-degron recognized by the DesCEND pathway is usually a motif of less than ten residues and can be present in full-length proteins, truncated proteins or proteolytically cleaved forms (PubMed:29779948, PubMed:33398168, PubMed:33398170). The CRL2(FEM1A) complex specifically recognizes proteins with an arginine at the C-terminus: recognizes and binds proteins ending with -Lys/Arg-Xaa-Arg and -Lys/Arg-Xaa-Xaa-Arg C-degrons, such as SIL1 or OR51B2, leading to their ubiquitination and degradation (PubMed:33398168, PubMed:33398170). Promotes ubiquitination and degradation of SLBP (PubMed:28118078). Involved in PGE2-EP4-mediated inhibition of inflammation of macrophages via interaction with NFKB1 and PTGER4 (By similarity). Promotes inflammation in brain microglia through MAP2K4/MKK4-mediated signaling (By similarity)","subunit":"Component of a CRL2 E3 ubiquitin-protein ligase complex, also named ECS (Elongin BC-CUL2/5-SOCS-box protein) complex, composed of CUL2, Elongin BC (ELOB and ELOC), RBX1 and substrate-specific adapter FEM1A (PubMed:29779948). Interacts with PTGER4 (PubMed:16424369). Interacts with NFKB1; the interaction is direct (By similarity)","family":"Belongs to the fem-1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["28118078","29779948","33398168","33398170"],"location":"Mitochondrion；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；注释原文：Substrate-recognition component of a Cul2-RING (CRL2) E3 ubiquitin-protein ligase complex of the DesCEND (destruction via C-end degrons) pathway, which recognizes a C-degron located at the extreme C terminus of target proteins, leading to their ubiquitination and degradation (PubMed:29779948, PubMed:33398168, PubMed:33398170).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；免疫/炎症/细胞死亡"},"FEN1":{"hgnc":"HGNC:3650","symbol":"FEN1","accessions":["P39748"],"name":"Flap endonuclease 1","length":"380","function":"Structure-specific nuclease with 5'-flap endonuclease and 5'-3' exonuclease activities involved in DNA replication and repair. During DNA replication, cleaves the 5'-overhanging flap structure that is generated by displacement synthesis when DNA polymerase encounters the 5'-end of a downstream Okazaki fragment. It enters the flap from the 5'-end and then tracks to cleave the flap base, leaving a nick for ligation. Also involved in the long patch base excision repair (LP-BER) pathway, by cleaving within the apurinic/apyrimidinic (AP) site-terminated flap. Acts as a genome stabilization factor that prevents flaps from equilibrating into structures that lead to duplications and deletions. Also possesses 5'-3' exonuclease activity on nicked or gapped double-stranded DNA, and exhibits RNase H activity. Also involved in replication and repair of rDNA and in repairing mitochondrial DNA","subunit":"Interacts with PCNA (PubMed:11430825, PubMed:15616578, PubMed:26760506, PubMed:9305916). Three molecules of FEN1 bind to one PCNA trimer with each molecule binding to one PCNA monomer (PubMed:15616578). PCNA stimulates the nuclease activity without altering cleavage specificity (PubMed:15616578). The C-terminal domain binds EP300; can bind simultaneously to both PCNA and EP300 (PubMed:11430825). Interacts with DDX11; this interaction is direct and increases flap endonuclease activity of FEN1 (PubMed:18499658). Interacts with WDR4; regulating its endonuclease activity (PubMed:26751069). Interacts with POLB (PubMed:19336415, PubMed:26760506)","family":"Belongs to the XPG/RAD2 endonuclease family. FEN1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10744741","11986308","18443037","20729856","26751069","7961795","8621570"],"location":"Nucleus, nucleolus；Nucleus, nucleoplasm；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；线粒体/代谢；注释原文：Structure-specific nuclease with 5'-flap endonuclease and 5'-3' exonuclease activities involved in DNA replication and repair.","function_evidence":"含实验支持条目；ECO:0000255,ECO:0000269","categories":"DNA修复/复制；线粒体/代谢"},"FERMT2":{"hgnc":"HGNC:15767","symbol":"FERMT2","accessions":["Q96AC1"],"name":"Fermitin family homolog 2","length":"680","function":"Scaffolding protein that enhances integrin activation mediated by TLN1 and/or TLN2, but activates integrins only weakly by itself. Binds to membranes enriched in phosphoinositides. Enhances integrin-mediated cell adhesion onto the extracellular matrix and cell spreading; this requires both its ability to interact with integrins and with phospholipid membranes. Required for the assembly of focal adhesions. Participates in the connection between extracellular matrix adhesion sites and the actin cytoskeleton and also in the orchestration of actin assembly and cell shape modulation. Recruits FBLIM1 to focal adhesions. Plays a role in the TGFB1 and integrin signaling pathways. Stabilizes active CTNNB1 and plays a role in the regulation of transcription mediated by CTNNB1 and TCF7L2/TCF4 and in Wnt signaling","subunit":"Interacts with ILK (By similarity). Interacts with FBLIM1. Interacts with ITGB1 and ITGB3. Interacts with active, unphosphorylated CTNNB1. Identified in a complex with CTNNB1 and TCF7L2/TCF4. Interacts with ITGB1; the interaction is inhibited in presence of ITGB1BP1","family":"Belongs to the kindlin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12679033","18458155","21325030","22030399","22078565","22699938"],"location":"Cytoplasm；Cytoplasm, cell cortex；Cytoplasm, cytoskeleton；Cytoplasm, cytoskeleton, stress fiber；Cell junction, focal adhesion；Membrane；Peripheral membrane protein；Cytoplasmic side；Cell projection, lamellipodium membrane；Nucleus；Cytoplasm, myofibril, sarcomere, I band；Cell surface","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面；注释原文：Scaffolding protein that enhances integrin activation mediated by TLN1 and/or TLN2, but activates integrins only weakly by itself.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面"},"FGF12":{"hgnc":"HGNC:3668","symbol":"FGF12","accessions":["P61328"],"name":"Fibroblast growth factor 12","length":"243","function":"Involved in nervous system development and function. Involved in the positive regulation of voltage-gated sodium channel activity. Promotes neuronal excitability by elevating the voltage dependence of neuronal sodium channel SCN8A fast inactivation","subunit":"Interacts with the C-terminal region of SCN9A","family":"Belongs to the heparin-binding growth factors family","domains":[],"function_pmids":["27164707"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in nervous system development and function. Involved in the positive regulation of voltage-gated sodium channel activity. Promotes neuronal excitability by elevating the voltage dependence of neuronal sodium channel SCN8A fast inactivation"},"FGF13":{"hgnc":"HGNC:3670","symbol":"FGF13","accessions":["Q92913"],"name":"Fibroblast growth factor 13","length":"245","function":"Microtubule-binding protein which directly binds tubulin and is involved in both polymerization and stabilization of microtubules (By similarity). Through its action on microtubules, may participate in the refinement of axons by negatively regulating axonal and leading processes branching (By similarity). Plays a crucial role in neuron polarization and migration in the cerebral cortex and the hippocampus (By similarity). Regulates voltage-gated sodium channel transport and function (PubMed:15282281, PubMed:33245860, PubMed:36696443). May also play a role in MAPK signaling (By similarity). Required for the development of axonal initial segment-targeting inhibitory GABAergic synapses made by chandelier neurons (By similarity)","subunit":"Interacts with SCN8A; regulates SCN8A activity (PubMed:15282281, PubMed:21566136, PubMed:33245860). Interacts with SCN1A; may regulate SCN1A activity (PubMed:19406745, PubMed:21566136). Interacts with SCN5A; the interaction is direct and may regulate SNC5A density at membranes and function (PubMed:21817159). May also interact with SCN2A and SCN11A (PubMed:19406745, PubMed:21566136). Interacts with MAPK8IP2; may regulate the MAPK8IP2 scaffolding activity (PubMed:11378392)","family":"Belongs to the heparin-binding growth factors family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15282281","33245860","36696443"],"location":"Nucleus；Cytoplasm；Cell projection, filopodium；Cell projection, growth cone；Cell projection, dendrite；Cell membrane, sarcolemma","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化；注释原文：Microtubule-binding protein which directly binds tubulin and is involved in both polymerization and stabilization of microtubules (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化"},"FGF3":{"hgnc":"HGNC:3681","symbol":"FGF3","accessions":["P11487"],"name":"Fibroblast growth factor 3","length":"239","function":"Plays an important role in the regulation of embryonic development, cell proliferation, and cell differentiation. Required for normal ear development","subunit":"Interacts with FGFR1 and FGFR2. Affinity between fibroblast growth factors (FGFs) and their receptors is increased by heparan sulfate glycosaminoglycans that function as coreceptors","family":"Belongs to the heparin-binding growth factors family","domains":[],"function_pmids":["8663044"],"location":"Secreted","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Plays an important role in the regulation of embryonic development, cell proliferation, and cell differentiation. Required for normal ear development"},"FGFR1":{"hgnc":"HGNC:3688","symbol":"FGFR1","accessions":["P11362"],"name":"Fibroblast growth factor receptor 1","length":"822","function":"Tyrosine-protein kinase that acts as a cell-surface receptor for fibroblast growth factors and plays an essential role in the regulation of embryonic development, cell proliferation, differentiation and migration. Required for normal mesoderm patterning and correct axial organization during embryonic development, normal skeletogenesis and normal development of the gonadotropin-releasing hormone (GnRH) neuronal system. Phosphorylates PLCG1, FRS2, GAB1 and SHB. Ligand binding leads to the activation of several signaling cascades. Activation of PLCG1 leads to the production of the cellular signaling molecules diacylglycerol and inositol 1,4,5-trisphosphate. Phosphorylation of FRS2 triggers recruitment of GRB2, GAB1, PIK3R1 and SOS1, and mediates activation of RAS, MAPK1/ERK2, MAPK3/ERK1 and the MAP kinase signaling pathway, as well as of the AKT1 signaling pathway. Promotes phosphorylation of SHC1, STAT1 and PTPN11/SHP2. In the nucleus, enhances RPS6KA1 and CREB1 activity and contributes to the regulation of transcription. FGFR1 signaling is down-regulated by IL17RD/SEF, and by FGFR1 ubiquitination, internalization and degradation","subunit":"Monomer. Homodimer after ligand binding. Interacts predominantly with FGF1 and FGF2, but can also interact with FGF3, FGF4, FGF5, FGF6, FGF8, FGF10, FGF19, FGF21, FGF22 and FGF23 (in vitro) (PubMed:12181353, PubMed:16597617, PubMed:1697263, PubMed:1722683, PubMed:17623664, PubMed:8663044, PubMed:9655399). Ligand specificity is determined by tissue-specific expression of isoforms, and differences in the third Ig-like domain are crucial for ligand specificity. Affinity for fibroblast growth factors (FGFs) is increased by heparan sulfate glycosaminoglycans that function as coreceptors. Likewise, KLB increases the affinity for FGF19, FGF21 and FGF23 (PubMed:19966287). Interacts (phosphorylated on Tyr-766) with PLCG1 (via SH2 domains) (PubMed:1379697, PubMed:1656221, PubMed:21765395). Interacts with FRS2 (PubMed:21765395). Interacts with RPS6KA1 (PubMed:15117958). Interacts (via C-terminus) with NEDD4 (via WW3 domain) (PubMed:21765395). Interacts with KL (By similarity). Interacts with SHB (via SH2 domain) (PubMed:12181353). Interacts with GRB10 (PubMed:10454568). Interacts with ANOS1; this interaction does not interfere with FGF2-binding to FGFR1, but prevents binding of heparin-bound FGF2 (PubMed:19696444). Interacts with SOX2 and SOX3. Interacts with FLRT1, FLRT2 and FLRT3 (By similarity). Found in a ternary complex with FGF1 and ITGAV:ITGB3 (PubMed:18441324, PubMed:20422052)","family":"Belongs to the protein kinase superfamily. Tyr protein kinase family. Fibroblast growth factor receptor subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10830168","11353842","12181353","1379697","1379698","15117958","16597617","17311277","17623664","18480409","19224897","19261810","19665973","20133753","20139426","21765395","8622701","8663044"],"location":"Cell membrane；Single-pass type I membrane protein；Nucleus；Cytoplasm, cytosol；Cytoplasmic vesicle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"FGF受体酪氨酸激酶；发育/增殖信号。","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；黏附/受体/细胞表面；发育/分化"},"FHL2":{"hgnc":"HGNC:3703","symbol":"FHL2","accessions":["Q14192"],"name":"Four and a half LIM domains protein 2","length":"279","function":"May function as a molecular transmitter linking various signaling pathways to transcriptional regulation. Negatively regulates the transcriptional repressor E4F1 and may function in cell growth. Inhibits the transcriptional activity of FOXO1 and its apoptotic function by enhancing the interaction of FOXO1 with SIRT1 and FOXO1 deacetylation. Negatively regulates the calcineurin/NFAT signaling pathway in cardiomyocytes (PubMed:28717008)","subunit":"Interacts with ZNF638 and TTN/titin (PubMed:11813260, PubMed:12432079). Interacts with E4F1 (PubMed:16652157). Interacts with GRB7 (PubMed:18853468). Interacts with SIRT1 and FOXO1 (PubMed:15692560). Interacts with CEFIP (PubMed:28717008). Interacts with calcineurin (By similarity). Interacts with FOXK1 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15692560","16652157","18853468","28717008"],"location":"Cytoplasm；Nucleus；Cytoplasm, myofibril, sarcomere, Z line","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May function as a molecular transmitter linking various signaling pathways to transcriptional regulation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"FHL3":{"hgnc":"HGNC:3704","symbol":"FHL3","accessions":["Q13643"],"name":"Four and a half LIM domains protein 3","length":"280","function":"Recruited by SOX15 to FOXK1 promoters where it acts as a transcriptional coactivator of FOXK1","subunit":"Interacts with SOX15; the interaction recruits FHL3 to FOXK1 promoters where it acts as a transcriptional coactivator of FOXK1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Recruited by SOX15 to FOXK1 promoters where it acts as a transcriptional coactivator of FOXK1","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"FHL5":{"hgnc":"HGNC:17371","symbol":"FHL5","accessions":["Q5TD97"],"name":"Four and a half LIM domains protein 5","length":"284","function":"May be involved in the regulation of spermatogenesis. Stimulates CREM transcriptional activity in a phosphorylation-independent manner","subunit":"Interacts with CREM (via the third LIM domain). Interacts (via second LIM domain) with SPAG8","family":"","domains":[],"function_pmids":["11327716"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May be involved in the regulation of spermatogenesis. Stimulates CREM transcriptional activity in a phosphorylation-independent manner"},"FIP1L1":{"hgnc":"HGNC:19124","symbol":"FIP1L1","accessions":["Q6UN15"],"name":"Pre-mRNA 3'-end-processing factor FIP1","length":"594","function":"Component of the cleavage and polyadenylation specificity factor (CPSF) complex that plays a key role in pre-mRNA 3'-end formation, recognizing the AAUAAA signal sequence and interacting with poly(A) polymerase and other factors to bring about cleavage and poly(A) addition. FIP1L1 contributes to poly(A) site recognition and stimulates poly(A) addition. Binds to U-rich RNA sequence elements surrounding the poly(A) site. May act to tether poly(A) polymerase to the CPSF complex","subunit":"Component of the cleavage and polyadenylation specificity factor (CPSF) complex, composed of CPSF1, CPSF2, CPSF3, CPSF4 and FIP1L1. Found in a complex with CPSF1, FIP1L1 and PAPOLA. Interacts with CPSF1, CPSF4, CSTF2 and CSTF3 (PubMed:14749727). Interacts with AHCYL1 (when phosphorylated); the interaction is direct and associates AHCYL1 with the CPSF complex and RNA (PubMed:19224921). Interacts with NUDT21/CPSF5; this interaction occurs in a RNA sequence-specific manner (PubMed:15937220). Interacts (preferentially via unphosphorylated form and Arg/Glu/Asp-rich domain) with CPSF6 (via Arg/Ser-rich domain); this interaction mediates, at least in part, the interaction between the CFIm and CPSF complexes and may be inhibited by CPSF6 hyper-phosphorylation (PubMed:29276085). Interacts (preferentially via unphosphorylated form and Arg/Asp/Glu-rich domain) with CPSF7 (via Arg/Ser-rich domain); this interaction mediates, at least in part, the interaction between the CFIm and CPSF complexes and may be inhibited by CPSF7 hyper-phosphorylation (PubMed:29276085). Interacts with PAPOLA; the interaction seems to be increased by the interaction with AHCYL1 (By similarity)","family":"Belongs to the FIP1 family","domains":[],"function_pmids":["14749727"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Component of the cleavage and polyadenylation specificity factor (CPSF) complex that plays a key role in pre-mRNA 3'-end formation, recognizing the AAUAAA signal sequence and interacting with poly(A) polymerase and other factors to bring about cleavage and poly(A) addition. FIP1L1 contributes to poly(A) site recognition and stimulates poly(A) addition. Binds to U-rich RNA sequence elements surrounding the poly(A) site. May act to tether poly(A) polymerase to the CPSF complex"},"FIRRM":{"hgnc":"HGNC:25565","symbol":"FIRRM","accessions":["Q9NSG2"],"name":"FIGNL1-interacting regulator of recombination and mitosis","length":"853","function":"Forms a complex with FIGL1, which regulates DNA double-strand break (DSB) repair via homologous recombination (HR) (PubMed:29608566, PubMed:37256941, PubMed:37347663, PubMed:37515771, PubMed:37556550, PubMed:38286805). The FIGNL1-FIRRM complex is essential for resolution of homologous recombination intermediates in response to DNA interstrand cross-links (ICLs) (PubMed:37256941, PubMed:37347663, PubMed:37515771, PubMed:37556550, PubMed:38286805). The complex regulates HR by promoting disassembly of RAD51 filaments from DNA and chromatin, thereby preventing DNA damage-independent RAD51 loading and persistent DNA accumulation of RAD51 recombinases (PubMed:37256941, PubMed:37347663, PubMed:37515771, PubMed:37556550, PubMed:38286805). It also regulates HR during meiosis by promoting dissociation of DMC1 filaments from DNA (By similarity). Within the complex, provides the ATPase activity to disassemble DMC1 and RAD51 filaments, while FIRRM directly binds single-stranded DNA to facilitate this unloading (PubMed:37556550). Independently of FIRRM, slso acts as a regulator of PLK1 kinase activity at kinetochores that promotes faithful chromosome segregation in prometaphase by bridging kinase and phosphatase activities (PubMed:34260926). Phosphorylation of FIRRM by PLK1 negatively regulates its interaction with the phosphatase, PPP1CC, thus creating a negative feedback loop for maintaining proper PLK1 kinase activity during mitosis (PubMed:34260926)","subunit":"Interacts with FIGNL1; forming the FIGNL1-FIRRM complex, which regulates homologous recombination (PubMed:29608566, PubMed:37256941, PubMed:37347663, PubMed:37515771, PubMed:37556550, PubMed:38286805). Interacts (via its N-terminal region) with PLK1; controls PLK1 kinase activity (PubMed:34260926). Interacts (via the KVVXF motif) with PPP1CC; controls PLK1 kinase activity (PubMed:34260926)","family":"Belongs to the FIRRM family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29608566","34260926","37256941","37347663","37515771","37556550","38286805"],"location":"Chromosome；Nucleus；Chromosome, centromere, kinetochore；Chromosome, centromere；Midbody；Cytoplasm, cytoskeleton, spindle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；注释原文：Forms a complex with FIGL1, which regulates DNA double-strand break (DSB) repair via homologous recombination (HR) (PubMed:29608566, PubMed:37256941, PubMed:37347663, PubMed:37515771, PubMed:37556550, PubMed:38286805).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号"},"FKBP15":{"hgnc":"HGNC:23397","symbol":"FKBP15","accessions":["Q5T1M5"],"name":"FK506-binding protein 15","length":"1219","function":"May be involved in the cytoskeletal organization of neuronal growth cones. Seems to be inactive as a PPIase (By similarity). Involved in the transport of early endosomes at the level of transition between microfilament-based and microtubule-based movement","subunit":"Interacts with WIP and actin (PubMed:19121306). Interacts with TBC1D23 (PubMed:29084197)","family":"Belongs to the FKBP-type PPIase family","domains":[],"function_pmids":["19121306"],"location":"Cytoplasm; Cell projection, axon; Early endosome","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May be involved in the cytoskeletal organization of neuronal growth cones. Seems to be inactive as a PPIase (By similarity). Involved in the transport of early endosomes at the level of transition between microfilament-based and microtubule-based movement"},"FKBP4":{"hgnc":"HGNC:3720","symbol":"FKBP4","accessions":["Q02790"],"name":"Peptidyl-prolyl cis-trans isomerase FKBP4","length":"459","function":"Immunophilin protein with PPIase and co-chaperone activities. Component of steroid receptors heterocomplexes through interaction with heat-shock protein 90 (HSP90). May play a role in the intracellular trafficking of heterooligomeric forms of steroid hormone receptors between cytoplasm and nuclear compartments. The isomerase activity controls neuronal growth cones via regulation of TRPC1 channel opening. Also acts as a regulator of microtubule dynamics by inhibiting MAPT/TAU ability to promote microtubule assembly. May have a protective role against oxidative stress in mitochondria","subunit":"Homodimer (By similarity). Interacts with GLMN (PubMed:12604780). Associates with HSP90AA1 and HSP70 in steroid hormone receptor complexes. Also interacts with peroxisomal phytanoyl-CoA alpha-hydroxylase (PHYH). Interacts with NR3C1 and dynein. Interacts with HSF1 in the HSP90 complex. Associates with tubulin. Interacts with MAPT/TAU (By similarity). Interacts (via TPR domain) with S100A1, S100A2 and S100A6; the interaction is Ca(2+) dependent. Interaction with S100A1 and S100A2 (but not with S100A6) leads to inhibition of FKBP4-HSP90 interaction. Interacts with dynein; causes partially NR3C1 transport to the nucleus","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["1279700","1376003","19945390","21730050","2378870"],"location":"Cytoplasm, cytosol；Mitochondrion；Nucleus；Cytoplasm, cytoskeleton；Cell projection, axon","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面；注释原文：Immunophilin protein with PPIase and co-chaperone activities.","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面"},"FKBP5":{"hgnc":"HGNC:3721","symbol":"FKBP5","accessions":["Q13451"],"name":"Peptidyl-prolyl cis-trans isomerase FKBP5","length":"457","function":"Immunophilin protein with PPIase and co-chaperone activities (PubMed:11350175). Component of unligated steroid receptors heterocomplexes through interaction with heat-shock protein 90 (HSP90). Plays a role in the intracellular trafficking of heterooligomeric forms of steroid hormone receptors maintaining the complex into the cytoplasm when unliganded (PubMed:12538866). Acts as a regulator of Akt/AKT1 activity by promoting the interaction between Akt/AKT1 and PHLPP1, thereby enhancing dephosphorylation and subsequent activation of Akt/AKT1 (PubMed:28147277, PubMed:28363942). Interacts with IKBKE and IKBKB which facilitates IKK complex assembly leading to increased IKBKE and IKBKB kinase activity, NF-kappa-B activation, and IFN production (PubMed:26101251, PubMed:31434731)","subunit":"Part of a heteromultimeric cytoplasmic complex with HSP90AA1, HSPA1A/HSPA1B and steroid receptors. Upon ligand binding dissociates from the complex and FKBP4 takes its place (By similarity). Interacts with functionally mature heterooligomeric progesterone receptor complexes along with HSP90 and TEBP (PubMed:7693698). Interacts with NR3C1 (By similarity). Interacts with Akt/AKT1 and PHLPP1; enhancing dephosphorylation and subsequent activation of Akt/AKT1 (PubMed:28147277). Interacts with IFI44L; this interaction modulates the kinase activity of IKBKB and IKBKE (PubMed:31434731). Interacts with IKBKB and IKBKE (PubMed:26101251, PubMed:31434731)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11350175","12538866","26101251","28147277","28363942","31434731"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Immunophilin protein with PPIase and co-chaperone activities (PubMed:11350175).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"FKBP6":{"hgnc":"HGNC:3722","symbol":"FKBP6","accessions":["O75344"],"name":"Inactive peptidyl-prolyl cis-trans isomerase FKBP6","length":"327","function":"Has an essential role in spermatogenesis (PubMed:36150389). It is required to repress transposable elements and prevent their mobilization, which is essential for the germline integrity (By similarity). Acts via the piRNA metabolic process, which mediates the repression of transposable elements during meiosis by forming complexes composed of piRNAs and Piwi proteins and govern the methylation and subsequent repression of transposons (By similarity). Acts as a co-chaperone via its interaction with HSP90 and is required for the piRNA amplification process, the secondary piRNA biogenesis (By similarity). May be required together with HSP90 in removal of 16 nucleotide ping-pong by-products from Piwi complexes, possibly facilitating turnover of Piwi complexes (By similarity)","subunit":"Interacts (via TPR repeats) with HSP90 (By similarity). Interacts with HSP72/HSPA2 and CLTC. Interacts with GAPDH; leading to inhibit GAPDH catalytic activity","family":"Belongs to the FKBP6 family","domains":[],"function_pmids":["36150389"],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Has an essential role in spermatogenesis (PubMed:36150389). It is required to repress transposable elements and prevent their mobilization, which is essential for the germline integrity (By similarity). Acts via the piRNA metabolic process, which mediates the repression of transposable elements during meiosis by forming complexes composed of piRNAs and Piwi proteins and govern the methylation and subsequent repression of transposons (By similarity). Acts as a co-chaperone via its interaction with HSP90 and is required for the piRNA amplification process, the secondary piRNA biogenesis (By similarity). May be required together with HSP90 in removal of 16 nucleotide ping-pong by-products from Piwi complexes, possibly facilitating turnover of Piwi complexes (By similarity)"},"FKRP":{"hgnc":"HGNC:17997","symbol":"FKRP","accessions":["Q9H9S5"],"name":"Ribitol 5-phosphate transferase FKRP","length":"495","function":"Catalyzes the transfer of a ribitol 5-phosphate from CDP-L-ribitol to the ribitol 5-phosphate previously attached by FKTN/fukutin to the phosphorylated O-mannosyl trisaccharide (N-acetylgalactosamine-beta-3-N-acetylglucosamine-beta-4-(phosphate-6-)mannose), a carbohydrate structure present in alpha-dystroglycan (DAG1) (PubMed:26923585, PubMed:27194101, PubMed:29477842, PubMed:31949166). This constitutes the second step in the formation of the ribose 5-phosphate tandem repeat which links the phosphorylated O-mannosyl trisaccharide to the ligand binding moiety composed of repeats of 3-xylosyl-alpha-1,3-glucuronic acid-beta-1 (PubMed:25279699, PubMed:26923585, PubMed:27194101, PubMed:29477842, PubMed:31949166)","subunit":"Homodimer; disulfide-linked (PubMed:21886772). Tetramer (PubMed:31949166). Forms a complex composed of FKRP, FKTN/fukutin, and RXYLT1/TMEM5 (PubMed:29477842). Also exists as large multimeric protein complexes (PubMed:25279699). May interact with the dystrophin-glycoprotein complex (DGC) (By similarity)","family":"Belongs to the LicD transferase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25279699","26923585","27194101","29477842","31949166"],"location":"Golgi apparatus membrane；Single-pass type II membrane protein；Secreted；Cell membrane, sarcolemma；Rough endoplasmic reticulum；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Catalyzes the transfer of a ribitol 5-phosphate from CDP-L-ribitol to the ribitol 5-phosphate previously attached by FKTN/fukutin to the phosphorylated O-mannosyl trisaccharide (N-acetylgalactosamine-beta-3-N-acetylglucosamine-beta-4-(phosphate-6-)mannose), a carbohydrate structure present in alpha-dystroglycan (DAG1) (PubMed:26923585, PubMed:27194101, PubMed:29477842, PubMed:31949166).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"FLAD1":{"hgnc":"HGNC:24671","symbol":"FLAD1","accessions":["Q8NFF5"],"name":"Bifunctional FAD diphosphatase/FAD synthase","length":"587","function":"This enzyme has two activities: FAD diphosphatase activity and FAD synthase activity (PubMed:16643857, PubMed:21924249, PubMed:21951714, PubMed:23443125, PubMed:25135855, PubMed:26277395, PubMed:27259049, PubMed:31351152, PubMed:38688286). FAD diphosphatase acts on FAD and NADH to produce FMN and NMNH(2-), respectively (PubMed:26277395, PubMed:31351152, PubMed:38688286). FAD synthase catalyzes the adenylation of flavin mononucleotide (FMN) to form flavin adenine dinucleotide (FAD) coenzyme (PubMed:16643857, PubMed:21924249, PubMed:21951714, PubMed:23443125, PubMed:27259049, PubMed:38688286). In addition to its catalytic activities, the protein also facilitates the delivery of FAD to client apo-flavoproteins (PubMed:25954742). The balance between FAD synthesis and hydrolysis may be regulated by redox-sensing cysteine residues (PubMed:25135855, PubMed:26277395). At a much lower rate, FAD synthase catalyzes the reverse pyrophosphorolytic reaction (PubMed:21951714, PubMed:23443125, PubMed:25135855, PubMed:26277395). FAD synthase can also convert roseoflavin mononucleotide (RoFMN) to roseoflavin adenine dinucleotide (RoFAD); RoFMN is produced by riboflavin kinase when acting on the antibiotic roseoflavin (RoF) (PubMed:21924249). FAD synthase cannot convert 8-demethyl-8-amino-riboflavin mononucleotide (AFMN) to 8-demethyl-8-amino-riboflavin adenine dinucleotide (AFAD); AFMN is produced by riboflavin kinase when acting on the antibiotic 8-demethyl-8-amino-riboflavin (AF) (PubMed:21924249)","subunit":"Dimer (PubMed:38688286). Interacts with KDM1A; which promotes KDM1A holoenzyme formation (PubMed:25954742). Interacts with DMGDH; which promotes DMGDH holoenzyme formation (PubMed:25954742)","family":"In the N-terminal section; belongs to the MoaB/Mog family\nIn the C-terminal section; belongs to the PAPS reductase family. FAD1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16643857","21924249","21951714","23443125","25135855","25954742","26277395","27259049","31351152","38688286"],"location":"Nucleus；Mitochondrion matrix；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：This enzyme has two activities: FAD diphosphatase activity and FAD synthase activity (PubMed:16643857, PubMed:21924249, PubMed:21951714, PubMed:23443125, PubMed:25135855, PubMed:26277395, PubMed:27259049, PubMed:31351152, PubMed:38688286).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"FLCN":{"hgnc":"HGNC:27310","symbol":"FLCN","accessions":["Q8NFG4"],"name":"Folliculin","length":"579","function":"Multi-functional protein, involved in both the cellular response to amino acid availability and in the regulation of glycolysis (PubMed:17028174, PubMed:18663353, PubMed:21209915, PubMed:24081491, PubMed:24095279, PubMed:31672913, PubMed:31704029, PubMed:32612235, PubMed:34381247, PubMed:36103527, PubMed:37079666). GTPase-activating protein that plays a key role in the cellular response to amino acid availability through regulation of the non-canonical mTORC1 signaling cascade controlling the MiT/TFE factors TFEB and TFE3 (PubMed:17028174, PubMed:18663353, PubMed:21209915, PubMed:24081491, PubMed:24095279, PubMed:24448649, PubMed:31672913, PubMed:31704029, PubMed:32612235, PubMed:36103527, PubMed:37079666). Activates mTORC1 by acting as a GTPase-activating protein: specifically stimulates GTP hydrolysis by RagC/RRAGC or RagD/RRAGD, promoting the conversion to the GDP-bound state of RagC/RRAGC or RagD/RRAGD, and thereby activating the kinase activity of mTORC1 (PubMed:24095279, PubMed:31672913, PubMed:31704029, PubMed:32612235, PubMed:37079666). The GTPase-activating activity is inhibited during starvation and activated in presence of nutrients (PubMed:31672913, PubMed:32612235). Acts as a key component for non-canonical mTORC1-dependent control of the MiT/TFE factors TFEB and TFE3, while it is not involved in mTORC1-dependent phosphorylation of canonical RPS6KB1/S6K1 and EIF4EBP1/4E-BP1 (PubMed:21209915, PubMed:24081491, PubMed:31672913, PubMed:32612235). In low-amino acid conditions, the lysosomal folliculin complex (LFC) is formed on the membrane of lysosomes, which inhibits the GTPase-activating activity of FLCN, inactivates mTORC1 and maximizes nuclear translocation of TFEB and TFE3 (PubMed:31672913). Upon amino acid restimulation, RagA/RRAGA (or RagB/RRAGB) nucleotide exchange promotes disassembly of the LFC complex and liberates the GTPase-activating activity of FLCN, leading to activation of mTORC1 and subsequent cytoplasmic retention of TFEB and TFE3 (PubMed:31672913). Indirectly acts as a positive regulator of Wnt signaling by promoting mTOR-dependent cytoplasmic retention of MiT/TFE factor TFE3 (PubMed:31272105). Required for the exit of hematopoietic stem cell from pluripotency by promoting mTOR-dependent cytoplasmic retention of TFE3, thereby increasing Wnt signaling (PubMed:30733432). Acts as an inhibitor of browning of adipose tissue by regulating mTOR-dependent cytoplasmic retention of TFE3 (By similarity). Involved in the control of embryonic stem cells differentiation; together with LAMTOR1 it is necessary to recruit and activate RagC/RRAGC and RagD/RRAGD at the lysosomes, and to induce exit of embryonic stem cells from pluripotency via non-canonical, mTOR-independent TFE3 inactivation (By similarity). In response to flow stress, regulates STK11/LKB1 accumulation and mTORC1 activation through primary cilia: may act by recruiting STK11/LKB1 to primary cilia for activation of AMPK resided at basal bodies, causing mTORC1 down-regulation (PubMed:27072130). Together with FNIP1 and/or FNIP2, regulates autophagy: following phosphorylation by ULK1, interacts with GABARAP and promotes autophagy (PubMed:25126726). Interaction with GABARAP also inhibits the non-canonical mTORC1 signaling cascade: GABARAP sequesters FLCN, thereby inactivating mTORC1 and promoting nuclear translocation of TFEB and TFE3 (PubMed:34597140, PubMed:39423796). Required for starvation-induced perinuclear clustering of lysosomes by promoting association of RILP with its effector RAB34 (PubMed:27113757). Regulates glycolysis by binding to lactate dehydrogenase LDHA, acting as an uncompetitive inhibitor (PubMed:34381247)","subunit":"Interacts (via C-terminus) with FNIP1 or FNIP2 (via C-terminus) (PubMed:17028174, PubMed:18403135, PubMed:18663353, PubMed:27353360, PubMed:36103527). Component of the lysosomal folliculin complex (LFC), composed of FLCN, FNIP1 (or FNIP2), RagA/RRAGA or RagB/RRAGB GDP-bound, RagC/RRAGC or RagD/RRAGD GTP-bound, and Ragulator (PubMed:31672913, PubMed:31704029, PubMed:36103527). Interaction with FNIP1 or FNIP2 mediates indirect interaction with the PRKAA1, PRKAB1 and PRKAG1 subunits of 5'-AMP-activated protein kinase (AMPK) (PubMed:17028174). Interacts with HSP90AA1 in the presence of FNIP1 (PubMed:27353360). Interacts with HSP70, STUB1, CDC37, AHSA1, CCT2, STIP1, PTGES3 and PPP5C (PubMed:27353360). Interacts with GABARAP; interaction takes place in the presence of FNIP1 and/or FNIP2 (PubMed:25126726). Interaction with GABARAP sequesters FLCN, thereby inactivating mTORC1 (PubMed:34597140). Interacts with RILP; the interaction is direct and promotes association between RILP and RAB34 (PubMed:27113757). Interacts with KIF3A and KIF3B (PubMed:27072130). Interacts with lactate dehydrogenase LDHA, but not LDHB; the interaction is direct, may preferentially bind LDHA dimers rather than tetramers, and regulates LDHA activity, acting as an uncompetitive inhibitor (PubMed:34381247)","family":"Belongs to the folliculin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17028174","18663353","21209915","24081491","24095279","24448649","25126726","27072130","27113757","30733432","31272105","31672913","31704029","32612235","34381247","34597140","36103527","37079666","39423796"],"location":"Lysosome membrane；Cytoplasm, cytosol；Cell projection, cilium；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Cytoplasm, cytoskeleton, spindle；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；发育/分化；注释原文：Multi-functional protein, involved in both the cellular response to amino acid availability and in the regulation of glycolysis (PubMed:17028174, PubMed:18663353, PubMed:21209915, PubMed:24081491, PubMed:24095279, PubMed:31672913, PubMed:31704029, PubMed:32612235, PubMed:34381247, PubMed:36103527, PubMed:37079666).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；发育/分化"},"FLG2":{"hgnc":"HGNC:33276","symbol":"FLG2","accessions":["Q5D862"],"name":"Filaggrin-2","length":"2391","function":"Essential for normal cell-cell adhesion in the cornified cell layers (PubMed:29758285). Important for proper integrity and mechanical strength of the stratum corneum of the epidermis (PubMed:29505760)","subunit":"无可用SUBUNIT段","family":"Belongs to the S100-fused protein family\nIn the N-terminal section; belongs to the S-100 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29505760","29758285"],"location":"Cytoplasm；Cytoplasmic granule","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；注释原文：Essential for normal cell-cell adhesion in the cornified cell layers (PubMed:29758285).","function_evidence":"含实验支持条目；ECO:0000269","categories":"黏附/受体/细胞表面"},"FLII":{"hgnc":"HGNC:3750","symbol":"FLII","accessions":["Q13045"],"name":"Protein flightless-1 homolog","length":"1269","function":"Is a regulator of actin polymerization, required for proper myofibril organization and regulation of the length of sarcomeric thin filaments (By similarity). It also plays a role in the assembly of cardiomyocyte cell adhesion complexes (By similarity). Regulates cytoskeletal rearrangements involved in cytokinesis and cell migration, by inhibiting Rac1-dependent paxillin phosphorylation (By similarity). May play a role as coactivator in transcriptional activation by hormone-activated nuclear receptors (NR) and acts in cooperation with NCOA2 and CARM1 (PubMed:14966289). Involved in estrogen hormone signaling","subunit":"Interacts with actin, ACTL6A, NCOA2 and CARM1 (PubMed:14966289, PubMed:9525888). Interacts with LRRFIP1, LRRFIP2 and MYD88 (PubMed:10366446, PubMed:19265123, PubMed:9525888, PubMed:9671805). Upon LPS stimulation, LRRFIP2 competes for MYD88-binding. LRRFIP1 constitutively blocks the interaction with MyD88, even in the absence of LPS. Interacts with the nuclear receptors ESR1 and THRB (PubMed:14966289). Interacts with SGK3 (PubMed:19293151). Interacts (via the gelsolin-like region) with TMOD1 (By similarity). Interacts with (via the gelsolin-like region) TMOD3 (PubMed:37126682). Interacts with LMOD2, VCL, GSN and DES (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14966289"],"location":"Nucleus；Cytoplasm, cytoskeleton；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Cell projection, podosome；Cell junction, focal adhesion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：Is a regulator of actin polymerization, required for proper myofibril organization and regulation of the length of sarcomeric thin filaments (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面"},"FLT4":{"hgnc":"HGNC:3767","symbol":"FLT4","accessions":["P35916"],"name":"Vascular endothelial growth factor receptor 3","length":"1363","function":"Tyrosine-protein kinase that acts as a cell-surface receptor for VEGFC and VEGFD, and plays an essential role in adult lymphangiogenesis and in the development of the vascular network and the cardiovascular system during embryonic development. Promotes proliferation, survival and migration of endothelial cells, and regulates angiogenic sprouting. Signaling by activated FLT4 leads to enhanced production of VEGFC, and to a lesser degree VEGFA, thereby creating a positive feedback loop that enhances FLT4 signaling. Modulates KDR signaling by forming heterodimers. The secreted isoform 3 may function as a decoy receptor for VEGFC and/or VEGFD and play an important role as a negative regulator of VEGFC-mediated lymphangiogenesis and angiogenesis. Binding of vascular growth factors to isoform 1 or isoform 2 leads to the activation of several signaling cascades; isoform 2 seems to be less efficient in signal transduction, because it has a truncated C-terminus and therefore lacks several phosphorylation sites. Mediates activation of the MAPK1/ERK2, MAPK3/ERK1 signaling pathway, of MAPK8 and the JUN signaling pathway, and of the AKT1 signaling pathway. Phosphorylates SHC1. Mediates phosphorylation of PIK3R1, the regulatory subunit of phosphatidylinositol 3-kinase. Promotes phosphorylation of MAPK8 at 'Thr-183' and 'Tyr-185', and of AKT1 at 'Ser-473'","subunit":"Interacts with VEGFC and VEGFD. Monomer in the absence of bound VEGFC or VEGFD. Homodimer in the presence of bound VEGFC or VEGFD. Can also form a heterodimer with KDR. Interacts with PTPN14; the interaction is enhanced by stimulation with VEGFC. Interacts with CRK, GRB2, PTK2/FAK1, SHC1, PIK3R1 and PTPN11/SHP-2. Identified in a complex with SRC and ITGB1","family":"Belongs to the protein kinase superfamily. Tyr protein kinase family. CSF-1/PDGF receptor subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11532940","15102829","15474514","16076871","16452200","17210781","19610651","19779139","20224550","20431062","20445537","21273538","7675451","8700872","9435229"],"location":"Cell membrane；Single-pass type I membrane protein；Cytoplasm；Nucleus；Secreted","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；黏附/受体/细胞表面；发育/分化；注释原文：Tyrosine-protein kinase that acts as a cell-surface receptor for VEGFC and VEGFD, and plays an essential role in adult lymphangiogenesis and in the development of the vascular network and the cardiovascular system during embryonic development.","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；黏附/受体/细胞表面；发育/分化"},"FLYWCH1":{"hgnc":"HGNC:25404","symbol":"FLYWCH1","accessions":["Q4VC44"],"name":"FLYWCH-type zinc finger-containing protein 1","length":"716","function":"Transcription cofactor (PubMed:30097457). Negatively regulates transcription activation by catenin beta-1 CTNNB1, perhaps acting by competing with TCF4 for CTNNB1 binding (PubMed:30097457). May play a role in DNA-damage response signaling (PubMed:33924684). Binds specifically to DNA sequences at peri-centromeric chromatin loci","subunit":"Interacts with CTNNB1 (when unphosphorylated), perhaps preventing interaction of CTNNB1 with TCF4, and thereby regulating transcription activation; phosphorylation of CTNNB1 may inhibit the interaction","family":"","domains":[],"function_pmids":["30097457","33924684","34408139"],"location":"Nucleus; Chromosome, centromere","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcription cofactor (PubMed:30097457). Negatively regulates transcription activation by catenin beta-1 CTNNB1, perhaps acting by competing with TCF4 for CTNNB1 binding (PubMed:30097457). May play a role in DNA-damage response signaling (PubMed:33924684). Binds specifically to DNA sequences at peri-centromeric chromatin loci"},"FLYWCH2":{"hgnc":"HGNC:25178","symbol":"FLYWCH2","accessions":["Q96CP2"],"name":"FLYWCH family member 2","length":"140","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FMR1":{"hgnc":"HGNC:3775","symbol":"FMR1","accessions":["Q06787"],"name":"Fragile X messenger ribonucleoprotein 1","length":"632","function":"Multifunctional polyribosome-associated RNA-binding protein that plays a central role in neuronal development and synaptic plasticity through the regulation of alternative mRNA splicing, mRNA stability, mRNA dendritic transport and postsynaptic local protein synthesis of target mRNAs (PubMed:12417522, PubMed:16631377, PubMed:18653529, PubMed:19166269, PubMed:23235829, PubMed:25464849). Acts as an mRNA regulator by mediating formation of some phase-separated membraneless compartment: undergoes liquid-liquid phase separation upon binding to target mRNAs, leading to assemble mRNAs into cytoplasmic ribonucleoprotein granules that concentrate mRNAs with associated regulatory factors (PubMed:12417522, PubMed:30765518, PubMed:31439799). Plays a role in the alternative splicing of its own mRNA (PubMed:18653529). Stabilizes the scaffolding postsynaptic density protein DLG4/PSD-95 and the myelin basic protein (MBP) mRNAs in hippocampal neurons and glial cells, respectively; this stabilization is further increased in response to metabotropic glutamate receptor (mGluR) stimulation (By similarity). Plays a role in selective delivery of a subset of dendritic mRNAs to synaptic sites in response to mGluR activation in a kinesin-dependent manner (By similarity). Undergoes liquid-liquid phase separation following phosphorylation and interaction with CAPRIN1, promoting formation of cytoplasmic ribonucleoprotein granules that concentrate mRNAs with factors that inhibit translation and mediate deadenylation of target mRNAs (PubMed:31439799). Acts as a repressor of mRNA translation in synaptic regions by mediating formation of neuronal ribonucleoprotein granules and promoting recruitmtent of EIF4EBP2 (PubMed:30765518). Plays a role as a repressor of mRNA translation during the transport of dendritic mRNAs to postsynaptic dendritic spines (PubMed:11157796, PubMed:11532944, PubMed:12594214, PubMed:23235829). Component of the CYFIP1-EIF4E-FMR1 complex which blocks cap-dependent mRNA translation initiation (By similarity). Represses mRNA translation by stalling ribosomal translocation during elongation (By similarity). Reports are contradictory with regards to its ability to mediate translation inhibition of MBP mRNA in oligodendrocytes (PubMed:23891804). Also involved in the recruitment of the RNA helicase MOV10 to a subset of mRNAs and hence regulates microRNA (miRNA)-mediated translational repression by AGO2 (PubMed:14703574, PubMed:17057366, PubMed:25464849). Facilitates the assembly of miRNAs on specific target mRNAs (PubMed:17057366). Also plays a role as an activator of mRNA translation of a subset of dendritic mRNAs at synapses (PubMed:19097999, PubMed:19166269). In response to mGluR stimulation, FMR1-target mRNAs are rapidly derepressed, allowing for local translation at synapses (By similarity). Binds to a large subset of dendritic mRNAs that encode a myriad of proteins involved in pre- and postsynaptic functions (PubMed:11157796, PubMed:11719189, PubMed:12594214, PubMed:17417632, PubMed:23235829, PubMed:24448548, PubMed:7692601). Binds to 5'-ACU[GU]-3' and/or 5'-[AU]GGA-3' RNA consensus sequences within mRNA targets, mainly at coding sequence (CDS) and 3'-untranslated region (UTR) and less frequently at 5'-UTR (PubMed:23235829). Binds to intramolecular G-quadruplex structures in the 5'- or 3'-UTRs of mRNA targets (PubMed:11719189, PubMed:18579868, PubMed:25464849, PubMed:25692235). Binds to G-quadruplex structures in the 3'-UTR of its own mRNA (PubMed:11532944, PubMed:12594214, PubMed:15282548, PubMed:18653529, PubMed:7692601). Also binds to RNA ligands harboring a kissing complex (kc) structure; this binding may mediate the association of FMR1 with polyribosomes (PubMed:15805463). Binds mRNAs containing U-rich target sequences (PubMed:12927206). Binds to a triple stem-loop RNA structure, called Sod1 stem loop interacting with FMRP (SoSLIP), in the 5'-UTR region of superoxide dismutase SOD1 mRNA (PubMed:19166269). Binds to the dendritic, small non-coding brain cytoplasmic RNA 1 (BC1); which may increase the association of the CYFIP1-EIF4E-FMR1 complex to FMR1 target mRNAs at synapses (By similarity). Plays a role in mRNA nuclear export (PubMed:31753916). Specifically recognizes and binds a subset of N6-methyladenosine (m6A)-containing mRNAs, promoting their nuclear export in a XPO1/CRM1-dependent manner (PubMed:31753916). Together with export factor NXF2, is involved in the regulation of the NXF1 mRNA stability in neurons (By similarity). Associates with export factor NXF1 mRNA-containing ribonucleoprotein particles (mRNPs) in a NXF2-dependent manner (By similarity). Binds to a subset of miRNAs in the brain (PubMed:14703574, PubMed:17057366). May associate with nascent transcripts in a nuclear protein NXF1-dependent manner (PubMed:18936162). In vitro, binds to RNA homomer; preferentially on poly(G) and to a lesser extent on poly(U), but not on poly(A) or poly(C) (PubMed:12950170, PubMed:15381419, PubMed:7688265, PubMed:7781595, PubMed:8156595). Moreover, plays a role in the modulation of the sodium-activated potassium channel KCNT1 gating activity (PubMed:20512134). Negatively regulates the voltage-dependent calcium channel current density in soma and presynaptic terminals of dorsal root ganglion (DRG) neurons, and hence regulates synaptic vesicle exocytosis (By similarity). Modulates the voltage-dependent calcium channel CACNA1B expression at the plasma membrane by targeting the channels for proteasomal degradation (By similarity). Plays a role in regulation of MAP1B-dependent microtubule dynamics during neuronal development (By similarity). Has been shown to play a translation-independent role in the modulation of presynaptic action potential (AP) duration and neurotransmitter release via large-conductance calcium-activated potassium (BK) channels in hippocampal and cortical excitatory neurons (PubMed:25561520). May be involved in the control of DNA damage response (DDR) mechanisms through the regulation of ATR-dependent signaling pathways such as histone H2AX/H2A.x and BRCA1 phosphorylations (PubMed:24813610). Forms a cytoplasmic messenger ribonucleoprotein (mRNP) network by packaging long mRNAs, serving as a scaffold that recruits proteins and signaling molecules. This network facilitates signaling reactions by maintaining proximity between kinases and substrates (PubMed:39106863)\nBinds to RNA homomer; preferentially on poly(G) and to a lesser extent on poly(U), but not on poly(A) or poly(C) (PubMed:24204304). May bind to RNA in Cajal bodies (PubMed:24204304)\n(Microbial infection) Acts as a positive regulator of influenza A virus (IAV) replication. Required for the assembly and nuclear export of the viral ribonucleoprotein (vRNP) components","subunit":"Homodimer (PubMed:12950170, PubMed:16636078, PubMed:39106863, PubMed:7489725). Forms heterodimer with FXR1; heterodimerization occurs in a methylation-dependent manner (PubMed:11157796, PubMed:16636078, PubMed:7489725). Forms heterodimer with FXR2 (PubMed:11157796, PubMed:7489725). Homooligomer (PubMed:11157796, PubMed:18664458). Component of the CYFIP1-EIF4E-FMR1 complex at least composed of CYFIP, EIF4E and FMR1; this mRNA cap binding complex formation increases in presence of the brain cytoplasmic RNA BC1 and is dynamically regulated in an activity-dependent manner to repress and then possibly release dendritic mRNAs for translation in response to mGluR stimulation (By similarity). Associates with the SMN core complex that contains SMN, GEMIN2/SIP1, DDX20/GEMIN3, GEMIN4, GEMIN5, GEMIN6, GEMIN7, GEMIN8 and STRAP/UNRIP (PubMed:18093976). Part of a ribonucleoprotein complex with AGO2/EIF2C2 and miRNAs (PubMed:14703574). Interacts with AGO2/EIF2C2 (PubMed:14703574). Interacts (via C-terminus) with CACNA1B; this interaction induces a decrease in the number of presynaptic functional CACNA1B channels at the cell surface (By similarity). Interacts with CYFIP1; this interaction recruits CYFIP1 to capped mRNA (By similarity). Interacts with CYFIP2 (By similarity). Interacts with EIF5; this interaction occurs in a RNA-dependent manner (By similarity). Interacts with dynein (By similarity). Interacts with FXR1 and FXR2 (PubMed:14532325, PubMed:15380484, PubMed:8668200). Interacts with methylated histone H3 (PubMed:24813610). Interacts with IGF2BP1; this interaction allows to recruit IGF2BP1 to mRNA in a FMR1-dependent manner (PubMed:15282548). Interacts (via N-terminus) with KCNMB4 (PubMed:25561520). Interacts with KCNT1 (via C-terminus); this interaction alters gating properties of KCNT1 (PubMed:20512134). Interacts (via phosphorylated form) with MCRS1 (via N-terminus) (PubMed:16571602). Interacts with MOV10; this interaction is direct, occurs in an RNA-dependent manner on polysomes and induces association of MOV10 with RNAs (PubMed:25464849). Interacts with MYO5A and PURA; these interactions occur in association with polyribosome (By similarity). Interacts with NCL (By similarity). Interacts with NUFIP1 (PubMed:10556305). Interacts (via N-terminus) with NUFIP2 (PubMed:12837692, PubMed:16407062). Interacts with NXF1; this interaction occurs in a mRNA-dependent and polyribosome-independent manner in the nucleus (PubMed:18936162). Interacts with NXF2 (via N-terminus); this interaction is direct and occurs in a NXF1 mRNA-containing mRNP complexes (By similarity). Interacts with RANBP9 (via C-terminus); this interaction is direct and inhibits binding of FMR1 to RNA homomer (PubMed:15381419). Interacts with RPLP0 (PubMed:15380484). Interacts (via C-terminus) with SMN (via C-terminus); this interaction is direct and occurs in a RNA-independent manner (PubMed:18093976). Interacts with TDRD3 (via C-terminus); this interaction is direct (PubMed:18632687, PubMed:18664458). Interacts with YBX1; this interaction occurs in association with polyribosome (By similarity). Interacts with nucleosome (PubMed:24813610). Associates with polyribosome; this association occurs in a mRNA-dependent manner (PubMed:11719188, PubMed:12594214, PubMed:19097999, PubMed:24448548, PubMed:9659908). Associates with cytoplasmic messenger ribonucleoprotein particles (mRNPs) (PubMed:12575950, PubMed:19097999, PubMed:7692601, PubMed:9659908). Associates with microtubules in a kinesin- and dynein-dependent manner (By similarity). Isoform 6 interacts (via N-terminus) with NCL (via C-terminus) (PubMed:24658146). Isoform 6 interacts with CYFIP2; this interaction occurs in a RNA-dependent manner (PubMed:24658146). Isoform 6 interacts with EIF5; this interaction occurs in a RNA-dependent manner (PubMed:24658146). Isoform 6 interacts with RPLP0 (PubMed:24658146). Interacts with HABP4 (PubMed:21771594). Interacts with SND1 (PubMed:14508492). Interacts (when phosphorylated by CK2) with CAPRIN1; interaction with CAPRIN1 promotes formation of a membraneless compartment (PubMed:31439799)\n(Microbial infection) Interacts (via KH 2 domain) with influenza A nucleoprotein (NP); this interaction occurs in a RNA-dependent manner and stimulates viral ribonucleoprotein (vRNP) assembly and subsequent RNA synthesis\n(Microbial infection) Interacts with Sindbis virus non-structural protein 3 (via C-terminus); this interaction inhibits the formation of host stress granules on viral mRNAs and the nsp3-FMR1 complexes bind viral RNAs and probably orchestrate the assembly of viral replication complexes","family":"Belongs to the FMR1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11157796","11532944","11719189","12417522","12594214","12927206","12950170","14703574","15282548","15381419","15805463","16631377","17057366","17417632","18579868","18653529","18936162","19097999","19166269","20512134","23235829","23891804","24204304","24448548","24514761","24813610","25464849","25561520","25692235","30765518","31439799","31753916","39106863","7688265","7692601","7781595","8156595"],"location":"Cytoplasm, Cytoplasmic ribonucleoprotein granule；Cytoplasm, Stress granule；Cytoplasm；Perikaryon；Cytoplasm, perinuclear region；Cell projection, neuron projection；Cell projection, axon；Cell projection, dendrite；Cell projection, dendritic spine；Synapse, synaptosome；Cell projection, growth cone；Cell projection, filopodium tip；Synapse；Postsynaptic cell membrane；Presynaptic cell membrane；Nucleus；Nucleus, nucleolus；Chromosome, centromere；Chromosome；Cell membrane；Nucleus, Cajal body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；核质运输；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；翻译/核糖体；黏附/受体/细胞表面；发育/分化；注释原文：Multifunctional polyribosome-associated RNA-binding protein that plays a central role in neuronal development and synaptic plasticity through the regulation of alternative mRNA splicing, mRNA stability, mRNA dendritic transport and postsynaptic local protein synthesis of target mRNAs (PubMed:12417522, PubMed:16631377, PubMed:18653529, PubMed:19166269, PubMed:23235829, PubMed:25464849).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；RNA加工/剪接；核质运输；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；翻译/核糖体；黏附/受体/细胞表面；发育/分化"},"FNDC11":{"hgnc":"HGNC:28764","symbol":"FNDC11","accessions":["Q9BVV2"],"name":"Fibronectin type III domain-containing protein 11","length":"318","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 210-307: Fibronectin type-III [ECO:0000255/PROSITE-ProRule/PRU00316]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FNDC3A":{"hgnc":"HGNC:20296","symbol":"FNDC3A","accessions":["Q9Y2H6"],"name":"Fibronectin type-III domain-containing protein 3A","length":"1198","function":"Mediates spermatid-Sertoli adhesion during spermatogenesis","subunit":"无可用SUBUNIT段","family":"Belongs to the FNDC3 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Golgi apparatus membrane；Single-pass membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Mediates spermatid-Sertoli adhesion during spermatogenesis","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"发育/分化"},"FOSB":{"hgnc":"HGNC:3797","symbol":"FOSB","accessions":["P53539"],"name":"Protein FosB","length":"338","function":"Heterodimerizes with proteins of the JUN family to form an AP-1 transcription factor complex, thereby enhancing their DNA binding activity to gene promoters containing an AP-1 consensus sequence 5'-TGA[GC]TCA-3' and enhancing their transcriptional activity (PubMed:12618758, PubMed:28981703). As part of the AP-1 complex, facilitates enhancer selection together with cell-type-specific transcription factors by collaboratively binding to nucleosomal enhancers and recruiting the SWI/SNF (BAF) chromatin remodeling complex to establish accessible chromatin (By similarity). Together with JUN, plays a role in activation-induced cell death of T cells by binding to the AP-1 promoter site of FASLG/CD95L, and inducing its transcription in response to activation of the TCR/CD3 signaling pathway (PubMed:12618758). Exhibits transactivation activity in vitro (By similarity). Involved in the display of nurturing behavior towards newborns (By similarity). May play a role in neurogenesis in the hippocampus and in learning and memory-related tasks by regulating the expression of various genes involved in neurogenesis, depression and epilepsy (By similarity). Implicated in behavioral responses related to morphine reward and spatial memory (By similarity)\nExhibits lower transactivation activity than isoform 1 in vitro (By similarity). The heterodimer with JUN does not display any transcriptional activity, and may thereby act as an transcriptional inhibitor (By similarity). May be involved in the regulation of neurogenesis in the hippocampus (By similarity). May play a role in synaptic modifications in nucleus accumbens medium spiny neurons and thereby play a role in adaptive and pathological reward-dependent learning, including maladaptive responses involved in drug addiction (By similarity). Seems to be more stably expressed with a half-life of ~9.5 hours in cell culture as compared to 1.5 hours half-life of isoform 1 (By similarity)","subunit":"Heterodimer; binds to DNA as heterodimer (PubMed:28981703). Component of an AP-1 transcription factor complex; composed of FOS-JUN heterodimers (By similarity). As part of the AP-1 transcription factor complex, forms heterodimers with JUN, JUNB or JUND, thereby binding to the AP-1 consensus sequence and stimulating transcription (PubMed:28981703). Interacts with the BAF multiprotein chromatin-remodeling complex subunits SMARCB1 and SMARCD1 (By similarity). Interacts with ARID1A and JUN (By similarity)\nHomodimer under oxidizing conditions and monomer under reducing conditions (in vitro) (PubMed:32542236). Heterodimer; binds to DNA as heterodimer (By similarity). Forms heterodimers with JUNB, JUN or JUND; thereby binding to the AP-1 consensus sequence but does not stimulate transcription (By similarity). Forms heterodimers with JUND under oxidizing conditions (PubMed:32542236)","family":"Belongs to the bZIP family. Fos subfamily","domains":[],"function_pmids":["12618758","28981703"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Heterodimerizes with proteins of the JUN family to form an AP-1 transcription factor complex, thereby enhancing their DNA binding activity to gene promoters containing an AP-1 consensus sequence 5'-TGA[GC]TCA-3' and enhancing their transcriptional activity (PubMed:12618758, PubMed:28981703). As part of the AP-1 complex, facilitates enhancer selection together with cell-type-specific transcription factors by collaboratively binding to nucleosomal enhancers and recruiting the SWI/SNF (BAF) chromatin remodeling complex to establish accessible chromatin (By similarity). Together with JUN, plays a role in activation-induced cell death of T cells by binding to the AP-1 promoter site of FASLG/CD95L, and inducing its transcription in response to activation of the TCR/CD3 signaling pathway (PubMed:12618758). Exhibits transactivation activity in vitro (By similarity). Involved in the display of nurturing behavior towards newborns (By similarity). May play a role in neurogenesis in the hippocampus and in learning and memory-related tasks by regulating the expression of various genes involved in neurogenesis, depression and epilepsy (By similarity). Implicated in behavioral responses related to morphine reward and spatial memory (By similarity)\nExhibits lower transactivation activity than isoform 1 in vitro (By similarity). The heterodimer with JUN does not display any transcriptional activity, and may thereby act as an transcriptional inhibitor (By similarity). May be involved in the regulation of neurogenesis in the hippocampus (By similarity). May play a role in synaptic modifications in nucleus accumbens medium spiny neurons and thereby play a role in adaptive and pathological reward-dependent learning, including maladaptive responses involved in drug addiction (By similarity). Seems to be more stably expressed with a half-life of ~9.5 hours in cell culture as compared to 1.5 hours half-life of isoform 1 (By similarity)"},"FOSL1":{"hgnc":"HGNC:13718","symbol":"FOSL1","accessions":["P15407"],"name":"Fos-related antigen 1","length":"271","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Heterodimer (By similarity). Interacts with the BAF multiprotein chromatin-remodeling complex subunits SMARCB1 and SMARCD1 (By similarity). Interacts with ARID1A and JUN (By similarity)","family":"Belongs to the bZIP family. Fos subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FOSL2":{"hgnc":"HGNC:3798","symbol":"FOSL2","accessions":["P15408"],"name":"Fos-related antigen 2","length":"326","function":"Controls osteoclast survival and size (By similarity). As a dimer with JUN, activates LIF transcription (By similarity). Activates CEBPB transcription in PGE2-activated osteoblasts (By similarity)","subunit":"Heterodimer (By similarity). Interacts with the BAF multiprotein chromatin-remodeling complex subunits SMARCB1 and SMARCD1 (By similarity). Interacts with ARID1A (By similarity). Interacts with JUN","family":"Belongs to the bZIP family. Fos subfamily","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Controls osteoclast survival and size (By similarity). As a dimer with JUN, activates LIF transcription (By similarity). Activates CEBPB transcription in PGE2-activated osteoblasts (By similarity)"},"FOXA1":{"hgnc":"HGNC:5021","symbol":"FOXA1","accessions":["P55317"],"name":"Hepatocyte nuclear factor 3-alpha","length":"472","function":"Transcription factor that is involved in embryonic development, establishment of tissue-specific gene expression and regulation of gene expression in differentiated tissues. Is thought to act as a 'pioneer' factor opening the compacted chromatin for other proteins through interactions with nucleosomal core histones and thereby replacing linker histones at target enhancer and/or promoter sites. Binds DNA with the consensus sequence 5'-[AC]A[AT]T[AG]TT[GT][AG][CT]T[CT]-3' (By similarity). Proposed to play a role in translating the epigenetic signatures into cell type-specific enhancer-driven transcriptional programs. Its differential recruitment to chromatin is dependent on distribution of histone H3 methylated at 'Lys-5' (H3K4me2) in estrogen-regulated genes. Involved in the development of multiple endoderm-derived organ systems such as liver, pancreas, lung and prostate; FOXA1 and FOXA2 seem to have at least in part redundant roles (By similarity). Modulates the transcriptional activity of nuclear hormone receptors. Is involved in ESR1-mediated transcription; required for ESR1 binding to the NKX2-1 promoter in breast cancer cells; binds to the RPRM promoter and is required for the estrogen-induced repression of RPRM. Involved in regulation of apoptosis by inhibiting the expression of BCL2. Involved in cell cycle regulation by activating expression of CDKN1B, alone or in conjunction with BRCA1. Originally described as a transcription activator for a number of liver genes such as AFP, albumin, tyrosine aminotransferase, PEPCK, etc. Interacts with the cis-acting regulatory regions of these genes. Involved in glucose homeostasis","subunit":"Binds DNA as a monomer (By similarity). Interacts with FOXA2. Interacts with NKX2-1. Interacts with HDAC7. Interacts with the histone H3-H4 heterodimer. Associates with nucleosomes containing histone H2A. Interacts with AR. Interacts with NR0B2 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16087863","16331276","18358809","19127412","19917725"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Transcription factor that is involved in embryonic development, establishment of tissue-specific gene expression and regulation of gene expression in differentiated tissues.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"FOXD2":{"hgnc":"HGNC:3803","symbol":"FOXD2","accessions":["O60548"],"name":"Forkhead box protein D2","length":"495","function":"Probable transcription factor involved in embryogenesis and somatogenesis","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Probable transcription factor involved in embryogenesis and somatogenesis"},"FOXD4L1":{"hgnc":"HGNC:18521","symbol":"FOXD4L1","accessions":["Q9NU39"],"name":"Forkhead box protein D4-like 1","length":"408","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FOXD4L3":{"hgnc":"HGNC:18523","symbol":"FOXD4L3","accessions":["Q6VB84"],"name":"Forkhead box protein D4-like 3","length":"417","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"FOXD4L4":{"hgnc":"HGNC:23762","symbol":"FOXD4L4","accessions":["Q8WXT5"],"name":"Forkhead box protein D4-like 4","length":"416","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"FOXD4L5":{"hgnc":"HGNC:18522","symbol":"FOXD4L5","accessions":["Q5VV16"],"name":"Forkhead box protein D4-like 5","length":"416","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"FOXD4L6":{"hgnc":"HGNC:31986","symbol":"FOXD4L6","accessions":["Q3SYB3"],"name":"Forkhead box protein D4-like 6","length":"417","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"DNA binding 108-202: Fork-head [ECO:0000255/PROSITE-ProRule/PRU00089]","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FOXE3":{"hgnc":"HGNC:3808","symbol":"FOXE3","accessions":["Q13461"],"name":"Forkhead box protein E3","length":"319","function":"Transcription factor that controls lens epithelial cell growth through regulation of proliferation, apoptosis and cell cycle (PubMed:22527307, PubMed:25504734). During lens development, controls the ratio of the lens fiber cells to the cells of the anterior lens epithelium by regulating the rate of proliferation and differentiation (By similarity). Controls lens vesicle closure and subsequent separation of the lens vesicle from ectoderm (By similarity). Controls the expression of DNAJB1 in a pathway that is crucial for the development of the anterior segment of the eye (PubMed:27218149)","subunit":"","family":"","domains":[],"function_pmids":["22527307","25504734","27218149"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcription factor that controls lens epithelial cell growth through regulation of proliferation, apoptosis and cell cycle (PubMed:22527307, PubMed:25504734). During lens development, controls the ratio of the lens fiber cells to the cells of the anterior lens epithelium by regulating the rate of proliferation and differentiation (By similarity). Controls lens vesicle closure and subsequent separation of the lens vesicle from ectoderm (By similarity). Controls the expression of DNAJB1 in a pathway that is crucial for the development of the anterior segment of the eye (PubMed:27218149)"},"FOXF2":{"hgnc":"HGNC:3810","symbol":"FOXF2","accessions":["Q12947"],"name":"Forkhead box protein F2","length":"444","function":"Probable transcription activator for a number of lung-specific genes (PubMed:8626802). Mediates up-regulation of the E3 ligase IRF2BPL and drives ubiquitination and degradation of CTNNB1 (PubMed:29374064)","subunit":"Interacts with the transcription factors TBP and TFIIB","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["29374064","8626802"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；注释原文：Probable transcription activator for a number of lung-specific genes (PubMed:8626802).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控"},"FOXH1":{"hgnc":"HGNC:3814","symbol":"FOXH1","accessions":["O75593"],"name":"Forkhead box protein H1","length":"365","function":"Transcriptional activator. Recognizes and binds to the DNA sequence 5'-TGT[GT][GT]ATT-3'. Required for induction of the goosecoid (GSC) promoter by TGF-beta or activin signaling. Forms a transcriptionally active complex containing FOXH1/SMAD2/SMAD4 on a site on the GSC promoter called TARE (TGF-beta/activin response element)","subunit":"Interacts with the MH2 domains of SMAD2 and SMAD3","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9702198"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Transcriptional activator.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"FOXI1":{"hgnc":"HGNC:3815","symbol":"FOXI1","accessions":["Q12951"],"name":"Forkhead box protein I1","length":"378","function":"Transcriptional activator required for the development of normal hearing, sense of balance and kidney function. Required for the expression of SLC26A4/PDS, JAG1 and COCH in a subset of epithelial cells and the development of the endolymphatic system in the inner ear. Also required for the expression of SLC4A1/AE1, SLC4A9/AE4, ATP6V1B1 and the differentiation of intercalated cells in the epithelium of distal renal tubules (By similarity)","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Transcriptional activator required for the development of normal hearing, sense of balance and kidney function.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；发育/分化"},"FOXI2":{"hgnc":"HGNC:32448","symbol":"FOXI2","accessions":["Q6ZQN5"],"name":"Forkhead box protein I2","length":"318","function":"Possible transcriptional activator","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Possible transcriptional activator"},"FOXK1":{"hgnc":"HGNC:23480","symbol":"FOXK1","accessions":["P85037"],"name":"Forkhead box protein K1","length":"733","function":"Transcriptional regulator involved in different processes such as glucose metabolism, aerobic glycolysis, muscle cell differentiation and autophagy (By similarity). Recognizes and binds the forkhead DNA sequence motif (5'-GTAAACA-3') and can both act as a transcription activator or repressor, depending on the context (PubMed:17670796). Together with FOXK2, acts as a key regulator of metabolic reprogramming towards aerobic glycolysis, a process in which glucose is converted to lactate in the presence of oxygen (By similarity). Acts by promoting expression of enzymes for glycolysis (such as hexokinase-2 (HK2), phosphofructokinase, pyruvate kinase (PKLR) and lactate dehydrogenase), while suppressing further oxidation of pyruvate in the mitochondria by up-regulating pyruvate dehydrogenase kinases PDK1 and PDK4 (By similarity). Probably plays a role in gluconeogenesis during overnight fasting, when lactate from white adipose tissue and muscle is the main substrate (By similarity). Involved in mTORC1-mediated metabolic reprogramming: in response to mTORC1 signaling, translocates into the nucleus and regulates the expression of genes associated with glycolysis and downstream anabolic pathways, such as HIF1A, thereby regulating glucose metabolism (By similarity). Together with FOXK2, acts as a negative regulator of autophagy in skeletal muscle: in response to starvation, enters the nucleus, binds the promoters of autophagy genes and represses their expression, preventing proteolysis of skeletal muscle proteins (By similarity). Acts as a transcriptional regulator of the myogenic progenitor cell population in skeletal muscle (By similarity). Binds to the upstream enhancer region (CCAC box) of myoglobin (MB) gene, regulating the myogenic progenitor cell population (By similarity). Promotes muscle progenitor cell proliferation by repressing the transcriptional activity of FOXO4, thereby inhibiting myogenic differentiation (By similarity). Involved in remodeling processes of adult muscles that occur in response to physiological stimuli (By similarity). Required to correct temporal orchestration of molecular and cellular events necessary for muscle repair (By similarity). Represses myogenic differentiation by inhibiting MEFC activity (By similarity). Positively regulates Wnt/beta-catenin signaling by translocating DVL into the nucleus (PubMed:25805136). Reduces virus replication, probably by binding the interferon stimulated response element (ISRE) to promote antiviral gene expression (PubMed:25852164). Accessory component of the polycomb repressive deubiquitinase (PR-DUB) complex; recruits the PR-DUB complex to specific FOXK1-bound genes (PubMed:24634419, PubMed:30664650). Acts as an indirect positive regulator of ferroptosis following phosphorylation by isoform Beta-II of PRKCB by promoting expression and subsequent secretion of LGALS13 (PubMed:40246981)","subunit":"Interacts with SIN3A and SIN3B (via PAH2) to form a complex which represses transcription (By similarity). Component of SIN3A-, but not SIN3B-, containing multiprotein complexes (By similarity). Interacts with FOXO4 and MEF2C; both interactions inhibit FOXO4 and MEF2C transactivation activity (By similarity). Interacts (when phosphorylated) with YWHAE/14-3-3-epsilon; promotes sequestration in the cytoplasm and leads to impaired ability to bind DNA (By similarity). Interacts with FHL2 (By similarity). Interacts with SRF (PubMed:17670796). Interacts with DVL2 and DVL3; the interaction induces DVL2 nuclear translocation (PubMed:25805136). Interacts with BAP1 (when phosphorylated) (PubMed:25451922). Accessory component of the polycomb repressive deubiquitinase (PR-DUB) complex, at least composed of BAP1, one of ASXL1, ASXL2 or (probably) ASXL3 and one of MBD5 or MBD6 (PubMed:24634419, PubMed:30664650). The PR-DUB core associates with a number of accessory proteins, including FOXK1, FOXK2, KDM1B, HCFC1 and OGT (Probable) (PubMed:30664650)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17670796","24634419","25805136","25852164","30664650","40246981"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：Transcriptional regulator involved in different processes such as glucose metabolism, aerobic glycolysis, muscle cell differentiation and autophagy (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"FOXK2":{"hgnc":"HGNC:6036","symbol":"FOXK2","accessions":["Q01167"],"name":"Forkhead box protein K2","length":"660","function":"Transcriptional regulator involved in different processes such as glucose metabolism, aerobic glycolysis and autophagy (PubMed:38735474). Recognizes and binds the forkhead DNA sequence motif (5'-GTAAACA-3') and can both act as a transcription activator or repressor, depending on the context (PubMed:22083952, PubMed:25451922). Together with FOXK1, acts as a key regulator of metabolic reprogramming towards aerobic glycolysis, a process in which glucose is converted to lactate in the presence of oxygen (By similarity). Acts by promoting expression of enzymes for glycolysis (such as hexokinase-2 (HK2), phosphofructokinase, pyruvate kinase (PKLR) and lactate dehydrogenase), while suppressing further oxidation of pyruvate in the mitochondria by up-regulating pyruvate dehydrogenase kinases PDK1 and PDK4 (By similarity). Probably plays a role in gluconeogenesis during overnight fasting, when lactate from white adipose tissue and muscle is the main substrate (By similarity). Together with FOXK1, acts as a negative regulator of autophagy in skeletal muscle: in response to starvation, enters the nucleus, binds the promoters of autophagy genes and represses their expression, preventing proteolysis of skeletal muscle proteins (By similarity). In addition to the 5'-GTAAACA-3' DNA motif, also binds the 5'-TGANTCA-3' palindromic DNA motif, and co-associates with JUN/AP-1 to activate transcription (PubMed:22083952). Also able to bind to a minimal DNA heteroduplex containing a G/T-mismatch with 5'-TRT[G/T]NB-3' sequence (PubMed:20097901). Binds to NFAT-like motifs (purine-rich) in the IL2 promoter (PubMed:1339390). Positively regulates WNT/beta-catenin signaling by translocating DVL proteins into the nucleus (PubMed:25805136). Also binds to HIV-1 long terminal repeat. May be involved in both positive and negative regulation of important viral and cellular promoter elements (PubMed:1909027). Accessory component of the polycomb repressive deubiquitinase (PR-DUB) complex; recruits the PR-DUB complex to specific FOXK2-bound genes (PubMed:24634419, PubMed:30664650)","subunit":"Component of SIN3A-, but not SIN3B-, containing multiprotein complexes (By similarity). Interacts with DVL1, DVL2 (when phosphorylated) and DVL3; the interaction induces DVL2 nuclear translocation (PubMed:25805136). Interacts with SUDS3 (PubMed:25805136). Interacts with BAP1 (when phosphorylated); leading to recruit the PR-DUB complex and repress FOXK2 target genes (PubMed:24748658, PubMed:25451922). Accessory component of the polycomb repressive deubiquitinase (PR-DUB) complex, at least composed of BAP1, one of ASXL1, ASXL2 or (probably) ASXL3 and one of MBD5 or MBD6 (PubMed:24634419, PubMed:30664650). The PR-DUB core associates with a number of accessory proteins, including FOXK1, FOXK2, KDM1B, HCFC1 and OGT (Probable) (PubMed:30664650). Interacts with FBXO24 (PubMed:38735474)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["1339390","1909027","20097901","22083952","24634419","25451922","25805136","30664650","38735474"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；线粒体/代谢；注释原文：Transcriptional regulator involved in different processes such as glucose metabolism, aerobic glycolysis and autophagy (PubMed:38735474).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；线粒体/代谢"},"FOXL1":{"hgnc":"HGNC:3817","symbol":"FOXL1","accessions":["Q12952"],"name":"Forkhead box protein L1","length":"345","function":"Transcription factor required for proper proliferation and differentiation in the gastrointestinal epithelium. Target gene of the hedgehog (Hh) signaling pathway via GLI2 and GLI3 transcription factors (By similarity)","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcription factor required for proper proliferation and differentiation in the gastrointestinal epithelium. Target gene of the hedgehog (Hh) signaling pathway via GLI2 and GLI3 transcription factors (By similarity)"},"FOXL2":{"hgnc":"HGNC:1092","symbol":"FOXL2","accessions":["P58012"],"name":"Forkhead box protein L2","length":"376","function":"Transcriptional regulator. Critical factor essential for ovary differentiation and maintenance, and repression of the genetic program for somatic testis determination. Prevents trans-differentiation of ovary to testis through transcriptional repression of the Sertoli cell-promoting gene SOX9 (By similarity). Has apoptotic activity in ovarian cells. Suppresses ESR1-mediated transcription of PTGS2/COX2 stimulated by tamoxifen (By similarity). Is a regulator of CYP19 expression (By similarity). Participates in SMAD3-dependent transcription of FST via the intronic SMAD-binding element (By similarity). Is a transcriptional repressor of STAR. Activates SIRT1 transcription under cellular stress conditions. Activates transcription of OSR2","subunit":"Interacts with ESR1 (By similarity). Interacts with SMAD3 (By similarity). Interacts with DDX20. Interacts with UBE2I/UBC9","family":"","domains":[],"function_pmids":["16153597","19010791","19429596","19744555"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcriptional regulator. Critical factor essential for ovary differentiation and maintenance, and repression of the genetic program for somatic testis determination. Prevents trans-differentiation of ovary to testis through transcriptional repression of the Sertoli cell-promoting gene SOX9 (By similarity). Has apoptotic activity in ovarian cells. Suppresses ESR1-mediated transcription of PTGS2/COX2 stimulated by tamoxifen (By similarity). Is a regulator of CYP19 expression (By similarity). Participates in SMAD3-dependent transcription of FST via the intronic SMAD-binding element (By similarity). Is a transcriptional repressor of STAR. Activates SIRT1 transcription under cellular stress conditions. Activates transcription of OSR2"},"FOXL2NB":{"hgnc":"HGNC:34428","symbol":"FOXL2NB","accessions":["Q6ZUU3"],"name":"FOXL2 neighbor protein","length":"175","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"FOXO1":{"hgnc":"HGNC:3819","symbol":"FOXO1","accessions":["Q12778"],"name":"Forkhead box protein O1","length":"655","function":"Transcription factor that is the main target of insulin signaling and regulates metabolic homeostasis in response to oxidative stress (PubMed:10358076, PubMed:12228231, PubMed:15220471, PubMed:15890677, PubMed:18356527, PubMed:19221179, PubMed:20543840, PubMed:21245099). Binds to the insulin response element (IRE) with consensus sequence 5'-TT[G/A]TTTTG-3' and the related Daf-16 family binding element (DBE) with consensus sequence 5'-TT[G/A]TTTAC-3' (PubMed:10358076). Activity suppressed by insulin (PubMed:10358076). Main regulator of redox balance and osteoblast numbers and controls bone mass (By similarity). Orchestrates the endocrine function of the skeleton in regulating glucose metabolism (By similarity). Also acts as a key regulator of chondrogenic commitment of skeletal progenitor cells in response to lipid availability: when lipids levels are low, translocates to the nucleus and promotes expression of SOX9, which induces chondrogenic commitment and suppresses fatty acid oxidation (By similarity). Acts synergistically with ATF4 to suppress osteocalcin/BGLAP activity, increasing glucose levels and triggering glucose intolerance and insulin insensitivity (By similarity). Also suppresses the transcriptional activity of RUNX2, an upstream activator of osteocalcin/BGLAP (By similarity). Acts as an inhibitor of glucose sensing in pancreatic beta cells by acting as a transcription repressor and suppressing expression of PDX1 (By similarity). In hepatocytes, promotes gluconeogenesis by acting together with PPARGC1A and CEBPA to activate the expression of genes such as IGFBP1, G6PC1 and PCK1 (By similarity). Also promotes gluconeogenesis by directly promoting expression of PPARGC1A and G6PC1 (PubMed:17024043). Important regulator of cell death acting downstream of CDK1, PKB/AKT1 and STK4/MST1 (PubMed:18356527, PubMed:19221179). Promotes neural cell death (PubMed:18356527). Mediates insulin action on adipose tissue (By similarity). Regulates the expression of adipogenic genes such as PPARG during preadipocyte differentiation and, adipocyte size and adipose tissue-specific gene expression in response to excessive calorie intake (By similarity). Regulates the transcriptional activity of GADD45A and repair of nitric oxide-damaged DNA in beta-cells (By similarity). Required for the autophagic cell death induction in response to starvation or oxidative stress in a transcription-independent manner (PubMed:20543840). Mediates the function of MLIP in cardiomyocytes hypertrophy and cardiac remodeling (By similarity). Positive regulator of apoptosis in cardiac smooth muscle cells as a result of its transcriptional activation of pro-apoptotic genes (PubMed:19483080). Regulates endothelial cell (EC) viability and apoptosis in a PPIA/CYPA-dependent manner via transcription of CCL2 and BCL2L11 which are involved in EC chemotaxis and apoptosis (PubMed:31063815)","subunit":"Interacts with LRPPRC. Interacts with RUNX2; the interaction inhibits RUNX2 transcriptional activity and mediates the IGF1/insulin-dependent BGLAP expression in osteoblasts Interacts with PPP2R1A; the interaction regulates the dephosphorylation of FOXO1 at Thr-24 and Ser-256 leading to its nuclear import. Interacts (acetylated form) with PPARG. Interacts with XBP1 isoform 2; this interaction is direct and leads to FOXO1 ubiquitination and degradation via the proteasome pathway (By similarity). Interacts with NLK. Interacts with SIRT1; the interaction results in the deacetylation of FOXO1 leading to activation of FOXO1-mediated transcription of genes involved in DNA repair and stress resistance. Binds to CDK1. Interacts with the 14-3-3 proteins, YWHAG and YWHAZ; the interactions require insulin-stimulated phosphorylation on Thr-24, promote nuclear exit and loss of transcriptional activity. Interacts with SKP2; the interaction ubiquitinates FOXO1 leading to its proteasomal degradation. The interaction requires the presence of KRIT1. Interacts (via the C-terminal half) with ATF4 (via its DNA-binding domain); the interaction occurs in osteoblasts, regulates glucose homeostasis via suppression of beta-cell proliferation and subsequent decrease in insulin production. Interacts with PRMT1; the interaction methylates FOXO1, prevents PKB/AKT1 phosphorylation and retains FOXO1 in the nucleus. Interacts with EP300 and CREBBP; the interactions acetylate FOXO1. Interacts with SIRT2; the interaction is disrupted in response to oxidative stress or serum deprivation, leading to increased level of acetylated FOXO1, which promotes stress-induced autophagy by stimulating E1-like activating enzyme ATG7. Interacts (acetylated form) with ATG7; the interaction is increased in response to oxidative stress or serum deprivation and promotes the autophagic process leading to cell death. Interacts (via the Fork-head domain) with CEBPA; the interaction increases when FOXO1 is deacetylated. Interacts with WDFY2. Forms a complex with WDFY2 and AKT1 (By similarity). Interacts with CRY1 (By similarity). Interacts with PPIA/CYPA; the interaction promotes FOXO1 dephosphorylation, nuclear accumulation and transcriptional activity (PubMed:31063815). Interacts with TOX4; FOXO1 is required for full induction of TOX4-dependent activity and the interaction is inhibited by insulin (By similarity). Interacts (when phosphorylated on Ser-256) with STUB1/CHIP (PubMed:19483080). Interacts with CTDSPL2 (PubMed:28851713)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10358076","12228231","15220471","15890677","17024043","18356527","19221179","19483080","20543840","21245099","31063815"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：Transcription factor that is the main target of insulin signaling and regulates metabolic homeostasis in response to oxidative stress (PubMed:10358076, PubMed:12228231, PubMed:15220471, PubMed:15890677, PubMed:18356527, PubMed:19221179, PubMed:20543840, PubMed:21245099).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"FOXP1":{"hgnc":"HGNC:3823","symbol":"FOXP1","accessions":["Q9H334"],"name":"Forkhead box protein P1","length":"677","function":"Transcriptional repressor (PubMed:18347093, PubMed:26647308). Can act with CTBP1 to synergistically repress transcription but CTPBP1 is not essential (By similarity). Plays an important role in the specification and differentiation of lung epithelium. Acts cooperatively with FOXP4 to regulate lung secretory epithelial cell fate and regeneration by restricting the goblet cell lineage program; the function may involve regulation of AGR2. Essential transcriptional regulator of B-cell development. Involved in regulation of cardiac muscle cell proliferation. Involved in the columnar organization of spinal motor neurons. Promotes the formation of the lateral motor neuron column (LMC) and the preganglionic motor column (PGC) and is required for respective appropriate motor axon projections. The segment-appropriate generation of spinal cord motor columns requires cooperation with other Hox proteins. Can regulate PITX3 promoter activity; may promote midbrain identity in embryonic stem cell-derived dopamine neurons by regulating PITX3. Negatively regulates the differentiation of T follicular helper cells T(FH)s. Involved in maintenance of hair follicle stem cell quiescence; the function probably involves regulation of FGF18 (By similarity). Represses transcription of various pro-apoptotic genes and cooperates with NF-kappa B-signaling in promoting B-cell expansion by inhibition of caspase-dependent apoptosis (PubMed:25267198). Binds to CSF1R promoter elements and is involved in regulation of monocyte differentiation and macrophage functions; repression of CSF1R in monocytes seems to involve NCOR2 as corepressor (PubMed:15286807, PubMed:18347093, PubMed:18799727). Involved in endothelial cell proliferation, tube formation and migration indicative for a role in angiogenesis; the role in neovascularization seems to implicate suppression of SEMA5B (PubMed:24023716). Can negatively regulate androgen receptor signaling (PubMed:18640093). Acts as a transcriptional activator of the FBXL7 promoter; this activity is regulated by AURKA (PubMed:28218735)\nInvolved in transcriptional regulation in embryonic stem cells (ESCs). Stimulates expression of transcription factors that are required for pluripotency and decreases expression of differentiation-associated genes. Has distinct DNA-binding specifities as compared to the canonical form and preferentially binds DNA with the sequence 5'-CGATACAA-3' (or closely related sequences) (PubMed:21924763). Promotes ESC self-renewal and pluripotency (By similarity)","subunit":"Forms homodimers and heterodimers with FOXP2 and FOXP4 (PubMed:25027557). Dimerization is required for DNA-binding. Self-associates (PubMed:26647308). Interacts with CTBP1 (By similarity). Interacts with NCOR2 and AR (PubMed:18347093, PubMed:18640093). Interacts with FOXP2 (PubMed:26647308). Interacts with TBR1 (PubMed:30250039). Interacts with AURKA; this interaction facilitates the phosphorylation of FOXP1, which suppresses the expression of FBXL7 (PubMed:28218735). Interacts with ZMYM2 (PubMed:32891193)","family":"","domains":[],"function_pmids":["15286807","18347093","18640093","18799727","21924763","24023716","25267198","26647308","28218735"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcriptional repressor (PubMed:18347093, PubMed:26647308). Can act with CTBP1 to synergistically repress transcription but CTPBP1 is not essential (By similarity). Plays an important role in the specification and differentiation of lung epithelium. Acts cooperatively with FOXP4 to regulate lung secretory epithelial cell fate and regeneration by restricting the goblet cell lineage program; the function may involve regulation of AGR2. Essential transcriptional regulator of B-cell development. Involved in regulation of cardiac muscle cell proliferation. Involved in the columnar organization of spinal motor neurons. Promotes the formation of the lateral motor neuron column (LMC) and the preganglionic motor column (PGC) and is required for respective appropriate motor axon projections. The segment-appropriate generation of spinal cord motor columns requires cooperation with other Hox proteins. Can regulate PITX3 promoter activity; may promote midbrain identity in embryonic stem cell-derived dopamine neurons by regulating PITX3. Negatively regulates the differentiation of T follicular helper cells T(FH)s. Involved in maintenance of hair follicle stem cell quiescence; the function probably involves regulation of FGF18 (By similarity). Represses transcription of various pro-apoptotic genes and cooperates with NF-kappa B-signaling in promoting B-cell expansion by inhibition of caspase-dependent apoptosis (PubMed:25267198). Binds to CSF1R promoter elements and is involved in regulation of monocyte differentiation and macrophage functions; repression of CSF1R in monocytes seems to involve NCOR2 as corepressor (PubMed:15286807, PubMed:18347093, PubMed:18799727). Involved in endothelial cell proliferation, tube formation and migration indicative for a role in angiogenesis; the role in neovascularization seems to implicate suppression of SEMA5B (PubMed:24023716). Can negatively regulate androgen receptor signaling (PubMed:18640093). Acts as a transcriptional activator of the FBXL7 promoter; this activity is regulated by AURKA (PubMed:28218735)\nInvolved in transcriptional regulation in embryonic stem cells (ESCs). Stimulates expression of transcription factors that are required for pluripotency and decreases expression of differentiation-associated genes. Has distinct DNA-binding specifities as compared to the canonical form and preferentially binds DNA with the sequence 5'-CGATACAA-3' (or closely related sequences) (PubMed:21924763). Promotes ESC self-renewal and pluripotency (By similarity)"},"FOXP2":{"hgnc":"HGNC:13875","symbol":"FOXP2","accessions":["O15409"],"name":"Forkhead box protein P2","length":"715","function":"Transcriptional repressor that may play a role in the specification and differentiation of lung epithelium. May also play a role in developing neural, gastrointestinal and cardiovascular tissues. Can act with CTBP1 to synergistically repress transcription but CTPBP1 is not essential. Plays a role in synapse formation by regulating SRPX2 levels. Involved in neural mechanisms mediating the development of speech and language","subunit":"Forms homodimers and heterodimers with FOXP1 and FOXP4. Dimerization is required for DNA-binding. Interacts with CTBP1 (By similarity). Interacts with FOXP1 (PubMed:26647308). Isoform 1 and isoform 3 interact with TBR1 (PubMed:25232744, PubMed:30250039). Interacts with ZMYM2 (PubMed:32891193)","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcriptional repressor that may play a role in the specification and differentiation of lung epithelium. May also play a role in developing neural, gastrointestinal and cardiovascular tissues. Can act with CTBP1 to synergistically repress transcription but CTPBP1 is not essential. Plays a role in synapse formation by regulating SRPX2 levels. Involved in neural mechanisms mediating the development of speech and language"},"FOXS1":{"hgnc":"HGNC:3735","symbol":"FOXS1","accessions":["O43638"],"name":"Forkhead box protein S1","length":"330","function":"Transcriptional repressor that suppresses transcription from the FASLG, FOXO3 and FOXO4 promoters. May have a role in the organization of the testicular vasculature (By similarity)","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Transcriptional repressor that suppresses transcription from the FASLG, FOXO3 and FOXO4 promoters.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"FPR1":{"hgnc":"HGNC:3826","symbol":"FPR1","accessions":["P21462"],"name":"N-formyl peptide receptor 1","length":"350","function":"Pattern recognition G protein-coupled receptor (PRR/GPCR) involved in innate recognition of N-formyl-methionyl peptides derived from invading microbes and host mitochondria as pathogen- and damage-associated molecular patterns (PAMPs and DAMPs). Functions as a sensor of PAMPs and DAMPs released upon microbial infection or tissue damage, triggering immune cell activation and chemotaxis to eliminate pathogens and restore tissue homeostasis (PubMed:24108355, PubMed:25605714, PubMed:35217703, PubMed:36064945). Peptide binding leads to conformational changes coupled to heterotrimeric G(i) protein signaling. Upon GDP to GTP conversion, G(i)-alpha subunit dissociates from G-beta and G-gamma subunits. Free G(i)-alpha subunit inhibits cyclic adenylate cyclase and cAMP synthesis whereas the G-beta and G-gamma dimer activates downstream phospholipase C-beta and phosphoinositide 3-kinase signaling cascades leading to Ca(2+) influx (PubMed:10514456, PubMed:15153520, PubMed:1712023, PubMed:25605714, PubMed:35217703, PubMed:36064945). Displays two affinity states for peptide agonists, low and high, likely accounting for selective signaling of myeloid cell functions at different phases of the inflammatory response. Subnanomolar concentrations of peptide agonists induce myeloid cell chemotaxis, whereas micromolar concentrations trigger degranulation and superoxide production (PubMed:2161213, PubMed:2176894, PubMed:24108355, PubMed:25605714). May recognize a myriad of bacterial signal peptides indicative of an evolutionary conserved detection mechanism in host defense against bacterial infection. Triggers bactericidal functions of neutrophils and phagocytes in response to N-formyl-Met-Leu-Phe (fMLF) which is part of the signal peptide sequences of hundreds distinct bacterial strains (PubMed:25605714). In the homeostatic wound healing response to tissue injury, senses 'necrotaxis' DAMP-type signals released in the form of mitochondria-derived N-formylated peptides and guides neutrophil trafficking toward necrotic cells within the injury site (By similarity). In the context of antitumor immunity, interacts with ANXA1 and guides dendritic cell positioning in close proximity to necrotic tumor cells, allowing for tumor-associated antigen uptake and cross-presentation to T cells (PubMed:24108355, PubMed:26516201). Receptor for TAFA4, mediates its effects on chemoattracting macrophages, promoting phagocytosis and increasing reactive oxygen species (ROS) release (PubMed:25109685). Receptor for cathepsin CTSG, leading to increased phagocyte chemotaxis (PubMed:15210802). Beyond canonical N-terminal formylated peptide agonists, can also be activated by C-terminal amidated peptides, which appear to all share a tripartite structure motif oriented around a carboxyl group (PubMed:24108355, PubMed:25605714). Differential signaling is also defined by receptor oligomerization state. Pro-resolving ligands, such as lipoxin A4 or ANXA1, induce the formation of FPR1:FPR2 heterodimers triggering proapoptotic JNK pathway in neutrophils (PubMed:24108355)\n(Microbial infection) Used by Y. pestis as a receptor on human immune cells. Upon infection, Y. pestis releases N-formyl peptides that activate FPR1-mediated immune signaling and chemotaxis. This leads to Y. pestis docking on FPR1 via the lcrV needle cap protein of its type III secretion system (T3SS) followed by the delivery of effector proteins into host immune cells, ultimately triggering immune cell apoptosis","subunit":"(Microbial infection) Interacts with S.aureus chemotaxis inhibitory protein (CHIPS); the interaction blocks the receptor and may thus inhibit the immune response\n(Microbial infection) Interacts with lcrV, the needle cap protein of the Y. pestis type III secretion system; this interaction promotes the translocation of bacterial effectors into host immune cells including neutrophils, macrophages and dendritic cells, thus targeting them for destruction\nHomodimer (PubMed:24108355). Heterodimer with FPR2 or FPR3; the heterodimerization with FPR2 is potentiated in response to anti-inflammatory agonists such as lipoxin A4 and ANXA1 (PubMed:24108355). Forms a complex with heterotrimeric G(i) protein composed of GNAI1, GNB1 and GNG2 subunits (PubMed:35217703, PubMed:36064945)","family":"Belongs to the G protein-coupled receptor 1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10514456","15153520","1712023","2161213","2176894","24108355","25109685","25605714","26516201","31534221","35217703","36064945"],"location":"Cell membrane；Multi-pass membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Pattern recognition G protein-coupled receptor (PRR/GPCR) involved in innate recognition of N-formyl-methionyl peptides derived from invading microbes and host mitochondria as pathogen- and damage-associated molecular patterns (PAMPs and DAMPs).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"FRA10AC1":{"hgnc":"HGNC:1162","symbol":"FRA10AC1","accessions":["Q70Z53"],"name":"Protein FRA10AC1","length":"315","function":"May be involved in pre-mRNA splicing","subunit":"Interacts with ESS2","family":"","domains":[],"function_pmids":["34694367"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May be involved in pre-mRNA splicing"},"FRG1":{"hgnc":"HGNC:3954","symbol":"FRG1","accessions":["Q14331"],"name":"Protein FRG1","length":"258","function":"Binds to mRNA in a sequence-independent manner. May play a role in regulation of pre-mRNA splicing or in the assembly of rRNA into ribosomal subunits. May be involved in mRNA transport. May be involved in epigenetic regulation of muscle differentiation through regulation of activity of the histone-lysine N-methyltransferase KMT5B","subunit":"Homodimer and homotetramer in solution. Identified in the spliceosome C complex. Interacts with KMT5B (via C-terminus). Interacts (via N-terminus) with KPNA2 and NXF1/TAP. Interacts with F-actin with a stoichiometry of 2:1. Interacts with GARIN3, SMN1 and PABPN1 (PubMed:17103222)","family":"Belongs to the FRG1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11991638","15060122","20970242","21699900","23720823"],"location":"Nucleus, Cajal body；Nucleus, nucleolus；Cytoplasm；Cytoplasm, myofibril, sarcomere, Z line","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化；注释原文：Binds to mRNA in a sequence-independent manner.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；发育/分化"},"FRG2":{"symbol":"FRG2","accessions":["Q64ET8"],"name":"Protein FRG2","length":278,"function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","domains":"InterPro: IPR026245 FRG2\nPfam: PF15315 FRG2","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类","location":"Nucleus","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"FRG2B":{"hgnc":"HGNC:33518","symbol":"FRG2B","accessions":["Q96QU4"],"name":"Protein FRG2-like-1","length":"278","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the FRG2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FRG2C":{"hgnc":"HGNC:33626","symbol":"FRG2C","accessions":["A6NGY1"],"name":"Protein FRG2-like-2","length":"282","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the FRG2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FRMD8":{"hgnc":"HGNC:25462","symbol":"FRMD8","accessions":["Q9BZ67"],"name":"FERM domain-containing protein 8","length":"464","function":"Promotes the cell surface stability of iRhom1/RHBDF1 and iRhom2/RHBDF2 and prevents their degradation via the endolysosomal pathway. By acting on iRhoms, involved in ADAM17-mediated shedding of TNF, amphiregulin/AREG, HBEGF and TGFA from the cell surface (PubMed:29897333, PubMed:29897336). Negatively regulates Wnt signaling, possibly by antagonizing the recruitment of AXIN1 to LRP6 (PubMed:19572019)","subunit":"Interacts with iRhom1/RHBDF1 and iRhom2/RHBDF2 (via cytoplasmic N-termini); this interaction leads to mutual protein stabilization (PubMed:29897333). Interacts with ADAM17; this interaction is indirect and mediated by iRhom proteins (PubMed:29897333, PubMed:29897336). Interacts with LRP6; this interaction affects LRP6-binding to AXIN1 (PubMed:19572019)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19572019","29897333","29897336"],"location":"Cytoplasm, cytosol；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Promotes the cell surface stability of iRhom1/RHBDF1 and iRhom2/RHBDF2 and prevents their degradation via the endolysosomal pathway.","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"FSAF1":{"hgnc":"HGNC:25332","symbol":"FSAF1","accessions":["Q8NDD1"],"name":"40S small subunit processome assembly factor 1","length":"293","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome. Prevents helicase DHX37 to be recruited before post-A1 state","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["34516797"],"location":"Chromosome；Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"FSBP":{"hgnc":"HGNC:43653","symbol":"FSBP","accessions":["O95073"],"name":"Fibrinogen silencer-binding protein","length":"299","function":"Transcriptional repressor that down-regulates the expression of the fibrinogen gamma chain. Represses transcription of GSK3B gene promoter via its interaction with APBA1","subunit":"Interacts with APBA1 (via PDZ 1 and 2 domains)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20531236"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Transcriptional repressor that down-regulates the expression of the fibrinogen gamma chain.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"FSD2":{"hgnc":"HGNC:18024","symbol":"FSD2","accessions":["A1L4K1"],"name":"Fibronectin type III and SPRY domain-containing protein 2","length":"749","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Interacts with CMYA5 (By similarity). In cardiac muscles, identified in a complex composed of FSD2, CMYA5 and RYR2 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Sarcoplasmic reticulum；Cytoplasm, perinuclear region","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"FST":{"hgnc":"HGNC:3971","symbol":"FST","accessions":["P19883"],"name":"Follistatin","length":"344","function":"Multifunctional regulatory protein whose primary function is to antagonize members of the transforming growth factor beta (TGF-beta) superfamily including activin, myostatin, GDF11 or bone morphogenetic proteins (BMPs) (PubMed:11279126, PubMed:16482217, PubMed:18535106). Mechanistically, binds to these ligands in the extracellular space, blocking their type II receptor-binding site to inhibit downstream signaling (PubMed:16482217). Plays an essential role in muscle fiber formation and growth both by preventing the repressive effects of myostatin and through SMAD3/AKT/mTOR signaling independently of myostatin (By similarity). Also promotes neural differentiation by antagonizing the action BMP4 (By similarity). Acts as a specific inhibitor of the biosynthesis and secretion of pituitary follicle stimulating hormone (FSH) by sequestering activin A/INHBA (PubMed:11279126). On the other hand, translocates into the nucleus where it down-regulates rRNA synthesis and ribosome biogenesis to maintain cellular energy homeostasis by binding to rDNA","subunit":"Interacts with GDF11 (PubMed:18535106, PubMed:28257634). Interacts with activin A/INHBA (PubMed:11279126, PubMed:16482217, PubMed:18535106, PubMed:16198295, PubMed:17409095). Interacts with MYOSTATIN/MSTN (PubMed:18535106)","family":"","domains":[],"function_pmids":["11279126","16482217","18535106"],"location":"Secreted; Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Multifunctional regulatory protein whose primary function is to antagonize members of the transforming growth factor beta (TGF-beta) superfamily including activin, myostatin, GDF11 or bone morphogenetic proteins (BMPs) (PubMed:11279126, PubMed:16482217, PubMed:18535106). Mechanistically, binds to these ligands in the extracellular space, blocking their type II receptor-binding site to inhibit downstream signaling (PubMed:16482217). Plays an essential role in muscle fiber formation and growth both by preventing the repressive effects of myostatin and through SMAD3/AKT/mTOR signaling independently of myostatin (By similarity). Also promotes neural differentiation by antagonizing the action BMP4 (By similarity). Acts as a specific inhibitor of the biosynthesis and secretion of pituitary follicle stimulating hormone (FSH) by sequestering activin A/INHBA (PubMed:11279126). On the other hand, translocates into the nucleus where it down-regulates rRNA synthesis and ribosome biogenesis to maintain cellular energy homeostasis by binding to rDNA"},"FTO":{"hgnc":"HGNC:24678","symbol":"FTO","accessions":["Q9C0B1"],"name":"Alpha-ketoglutarate-dependent dioxygenase FTO","length":"505","function":"RNA demethylase that mediates oxidative demethylation of different RNA species, such as mRNAs, tRNAs and snRNAs, and acts as a regulator of fat mass, adipogenesis and energy homeostasis (PubMed:22002720, PubMed:25452335, PubMed:26457839, PubMed:26458103, PubMed:28002401, PubMed:30197295). Specifically demethylates N(6)-methyladenosine (m6A) RNA, the most prevalent internal modification of messenger RNA (mRNA) in higher eukaryotes (PubMed:22002720, PubMed:25452335, PubMed:26457839, PubMed:26458103, PubMed:30197295). M6A demethylation by FTO affects mRNA expression and stability (PubMed:30197295). Also able to demethylate m6A in U6 small nuclear RNA (snRNA) (PubMed:30197295). Mediates demethylation of N(6),2'-O-dimethyladenosine cap (m6A(m)), by demethylating the N(6)-methyladenosine at the second transcribed position of mRNAs and U6 snRNA (PubMed:28002401, PubMed:30197295). Demethylation of m6A(m) in the 5'-cap by FTO affects mRNA stability by promoting susceptibility to decapping (PubMed:28002401). Also acts as a tRNA demethylase by removing N(1)-methyladenine from various tRNAs (PubMed:30197295). Has no activity towards 1-methylguanine (PubMed:20376003). Has no detectable activity towards double-stranded DNA (PubMed:20376003). Also able to repair alkylated DNA and RNA by oxidative demethylation: demethylates single-stranded RNA containing 3-methyluracil, single-stranded DNA containing 3-methylthymine and has low demethylase activity towards single-stranded DNA containing 1-methyladenine or 3-methylcytosine (PubMed:18775698, PubMed:20376003). Ability to repair alkylated DNA and RNA is however unsure in vivo (PubMed:18775698, PubMed:20376003). Involved in the regulation of fat mass, adipogenesis and body weight, thereby contributing to the regulation of body size and body fat accumulation (PubMed:18775698, PubMed:20376003). Involved in the regulation of thermogenesis and the control of adipocyte differentiation into brown or white fat cells (PubMed:26287746). Regulates activity of the dopaminergic midbrain circuitry via its ability to demethylate m6A in mRNAs (By similarity). Plays an oncogenic role in a number of acute myeloid leukemias by enhancing leukemic oncogene-mediated cell transformation: acts by mediating m6A demethylation of target transcripts such as MYC, CEBPA, ASB2 and RARA, leading to promote their expression (PubMed:28017614, PubMed:29249359)","subunit":"Monomer (By similarity). May also exist as homodimer (By similarity)","family":"Belongs to the fto family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18775698","20376003","22002720","25452335","26287746","26457839","26458103","28002401","28017614","29249359","30197295"],"location":"Nucleus；Nucleus speckle；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；发育/分化；注释原文：RNA demethylase that mediates oxidative demethylation of different RNA species, such as mRNAs, tRNAs and snRNAs, and acts as a regulator of fat mass, adipogenesis and energy homeostasis (PubMed:22002720, PubMed:25452335, PubMed:26457839, PubMed:26458103, PubMed:28002401, PubMed:30197295).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"翻译/核糖体；发育/分化"},"FTSJ3":{"hgnc":"HGNC:17136","symbol":"FTSJ3","accessions":["Q8IY81"],"name":"pre-rRNA 2'-O-ribose RNA methyltransferase FTSJ3","length":"847","function":"RNA 2'-O-methyltransferase involved in the processing of the 34S pre-rRNA to 18S rRNA and in 40S ribosomal subunit formation\n(Microbial infection) In case of infection by HIV-1 virus, recruited to HIV-1 RNA and catalyzes 2'-O-methylation of the viral genome, allowing HIV-1 virus to escape the innate immune system (PubMed:30626973). RNA 2'-O-methylation provides a molecular signature for discrimination of self from non-self and is used by HIV-1 to evade innate immune recognition by IFIH1/MDA5 (PubMed:30626973). Mediates methylation of internal residues of HIV-1 RNA, with a strong preference for adenosine (PubMed:30626973). Recruited to HIV-1 RNA via interaction with TARBP2/TRBP (PubMed:30626973)","subunit":"Interacts with NIP7\n(Microbial infection) Interacts with TARBP2/TRBP in case of infection by HIV-1; leading to recruitment to HIV-1 TAR RNA (PubMed:30626973). The complex formed with TARBP2/TRBP is independent of DICER (PubMed:30626973)","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. RNA methyltransferase RlmE family. SPB1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22195017","30626973"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；免疫/炎症/细胞死亡；注释原文：RNA 2'-O-methyltransferase involved in the processing of the 34S pre-rRNA to 18S rRNA and in 40S ribosomal subunit formation\n(Microbial infection) In case of infection by HIV-1 virus, recruited to HIV-1 RNA and catalyzes 2'-O-methylation of the viral genome, allowing HIV-1 virus to escape the innate immune system (PubMed:30626973).","function_evidence":"含实验支持条目；ECO:0000255,ECO:0000269","categories":"翻译/核糖体；免疫/炎症/细胞死亡"},"FUBP1":{"hgnc":"HGNC:4004","symbol":"FUBP1","accessions":["Q96AE4"],"name":"Far upstream element-binding protein 1","length":"644","function":"Regulates MYC expression by binding to a single-stranded far-upstream element (FUSE) upstream of the MYC promoter. May act both as activator and repressor of transcription","subunit":"Found in a complex with PUF60 and far upstream element (FUSE) DNA segment. Interacts with PUF60 and JTV1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["8125259"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Regulates MYC expression by binding to a single-stranded far-upstream element (FUSE) upstream of the MYC promoter.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"FUBP3":{"hgnc":"HGNC:4005","symbol":"FUBP3","accessions":["Q96I24"],"name":"Far upstream element-binding protein 3","length":"572","function":"May interact with single-stranded DNA from the far-upstream element (FUSE). May activate gene expression","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：May interact with single-stranded DNA from the far-upstream element (FUSE).","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"FUNDC2":{"hgnc":"HGNC:24925","symbol":"FUNDC2","accessions":["Q9BWH2"],"name":"FUN14 domain-containing protein 2","length":"189","function":"Binds directly and specifically 1,2-Diacyl-sn-glycero-3-phospho-(1'-myo-inositol-3',4',5'-bisphosphate) (PIP3) leading to the recruitment of PIP3 to mitochondria and may play a role in the regulation of the platelet activation via AKT/GSK3B/cGMP signaling pathways (PubMed:29786068). May act as transcription factor that regulates SREBP1 (isoform SREBP-1C) expression in order to modulate triglyceride (TG) homeostasis in hepatocytes (PubMed:25855506, PubMed:29187281)","subunit":"","family":"Belongs to the FUN14 family","domains":[],"function_pmids":["25855506","29187281","29786068"],"location":"Mitochondrion outer membrane; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Binds directly and specifically 1,2-Diacyl-sn-glycero-3-phospho-(1'-myo-inositol-3',4',5'-bisphosphate) (PIP3) leading to the recruitment of PIP3 to mitochondria and may play a role in the regulation of the platelet activation via AKT/GSK3B/cGMP signaling pathways (PubMed:29786068). May act as transcription factor that regulates SREBP1 (isoform SREBP-1C) expression in order to modulate triglyceride (TG) homeostasis in hepatocytes (PubMed:25855506, PubMed:29187281)"},"FURIN":{"hgnc":"HGNC:8568","symbol":"FURIN","accessions":["P09958"],"name":"Furin","length":"794","function":"Ubiquitous endoprotease within constitutive secretory pathways capable of cleavage at the RX(K/R)R consensus motif (PubMed:11799113, PubMed:1629222, PubMed:1713771, PubMed:2251280, PubMed:24666235, PubMed:25974265, PubMed:7592877, PubMed:7690548, PubMed:9130696). Mediates processing of TGFB1, an essential step in TGF-beta-1 activation (PubMed:7737999). Converts through proteolytic cleavage the non-functional Brain natriuretic factor prohormone into its active hormone BNP(1-32) (PubMed:20489134, PubMed:21763278). By mediating processing of accessory subunit ATP6AP1/Ac45 of the V-ATPase, regulates the acidification of dense-core secretory granules in islets of Langerhans cells (By similarity)\n(Microbial infection) Cleaves and activates diphtheria toxin DT\n(Microbial infection) Cleaves and activates anthrax toxin protective antigen (PA)\n(Microbial infection) Cleaves and activates HIV-1 virus Envelope glycoprotein gp160\n(Microbial infection) Required for H7N1 and H5N1 influenza virus infection probably by cleaving hemagglutinin\n(Microbial infection) Able to cleave S.pneumoniae serine-rich repeat protein PsrP\n(Microbial infection) Facilitates human coronaviruses EMC and SARS-CoV-2 infections by proteolytically cleaving the spike protein at the monobasic S1/S2 cleavage site. This cleavage is essential for spike protein-mediated cell-cell fusion and entry into human lung cells\n(Microbial infection) Facilitates mumps virus infection by proteolytically cleaving the viral fusion protein F","subunit":"Interacts with FLNA (By similarity). Binds to PACS1 which mediates TGN localization and connection to clathrin adapters (PubMed:11331585). Interacts with LAMP1, LAMP2 and LAMP3 (PubMed:32295904)","family":"Belongs to the peptidase S8 family. Furin subfamily","domains":[],"function_pmids":["11799113","1438214","1629222","1644824","1713771","20489134","21763278","2251280","24666235","25974265","27582320","31091448","32295904","32362314","32703818","7592877","7690548","7737999","8253774","9130696"],"location":"Golgi apparatus, trans-Golgi network membrane; Cell membrane; Secreted; Endosome membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Ubiquitous endoprotease within constitutive secretory pathways capable of cleavage at the RX(K/R)R consensus motif (PubMed:11799113, PubMed:1629222, PubMed:1713771, PubMed:2251280, PubMed:24666235, PubMed:25974265, PubMed:7592877, PubMed:7690548, PubMed:9130696). Mediates processing of TGFB1, an essential step in TGF-beta-1 activation (PubMed:7737999). Converts through proteolytic cleavage the non-functional Brain natriuretic factor prohormone into its active hormone BNP(1-32) (PubMed:20489134, PubMed:21763278). By mediating processing of accessory subunit ATP6AP1/Ac45 of the V-ATPase, regulates the acidification of dense-core secretory granules in islets of Langerhans cells (By similarity)\n(Microbial infection) Cleaves and activates diphtheria toxin DT\n(Microbial infection) Cleaves and activates anthrax toxin protective antigen (PA)\n(Microbial infection) Cleaves and activates HIV-1 virus Envelope glycoprotein gp160\n(Microbial infection) Required for H7N1 and H5N1 influenza virus infection probably by cleaving hemagglutinin\n(Microbial infection) Able to cleave S.pneumoniae serine-rich repeat protein PsrP\n(Microbial infection) Facilitates human coronaviruses EMC and SARS-CoV-2 infections by proteolytically cleaving the spike protein at the monobasic S1/S2 cleavage site. This cleavage is essential for spike protein-mediated cell-cell fusion and entry into human lung cells\n(Microbial infection) Facilitates mumps virus infection by proteolytically cleaving the viral fusion protein F"},"FUT8":{"hgnc":"HGNC:4019","symbol":"FUT8","accessions":["Q9BYC5"],"name":"Alpha-(1,6)-fucosyltransferase","length":"575","function":"Catalyzes the addition of fucose in alpha 1-6 linkage to the first GlcNAc residue, next to the peptide chains in N-glycans (PubMed:17172260, PubMed:29304374, PubMed:36280670, PubMed:9133635). Fucosylates the reducing GlcNAc residue in complex-type N-glycans attached on the fragment crystallizable (Fc) of IgGs. Fully converts Fc glycoforms containing one or two terminal GlcNAc moieties (G0-GlcNAc and G0) (PubMed:36280670)","subunit":"无可用SUBUNIT段","family":"Belongs to the glycosyltransferase 23 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17172260","29304374","36280670","9133635"],"location":"Golgi apparatus, Golgi stack membrane；Single-pass type II membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Catalyzes the addition of fucose in alpha 1-6 linkage to the first GlcNAc residue, next to the peptide chains in N-glycans (PubMed:17172260, PubMed:29304374, PubMed:36280670, PubMed:9133635).","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"FXR1":{"hgnc":"HGNC:4023","symbol":"FXR1","accessions":["P51114"],"name":"RNA-binding protein FXR1","length":"621","function":"mRNA-binding protein that acts as a regulator of mRNAs translation and/or stability, and which is required for various processes, such as neurogenesis, muscle development and spermatogenesis (PubMed:17382880, PubMed:20417602, PubMed:30067974, PubMed:34731628, PubMed:35989368, PubMed:36306353). Specifically binds to AU-rich elements (AREs) in the 3'-UTR of target mRNAs (PubMed:17382880, PubMed:34731628). Promotes formation of some phase-separated membraneless compartment by undergoing liquid-liquid phase separation upon binding to AREs-containing mRNAs, leading to assemble mRNAs into cytoplasmic ribonucleoprotein granules that concentrate mRNAs with associated regulatory factors (By similarity). Required to activate translation of stored mRNAs during late spermatogenesis: acts by undergoing liquid-liquid phase separation to assemble target mRNAs into cytoplasmic ribonucleoprotein granules that recruit translation initiation factor EIF4G3 to activate translation of stored mRNAs in late spermatids (By similarity). Promotes translation of MYC transcripts by recruiting the eIF4F complex to the translation start site (PubMed:34731628). Acts as a negative regulator of inflammation in response to IL19 by promoting destabilization of pro-inflammatory transcripts (PubMed:30067974). Also acts as an inhibitor of inflammation by binding to TNF mRNA, decreasing TNF protein production (By similarity). Acts as a negative regulator of AMPA receptor GRIA2/GluA2 synthesis during long-lasting synaptic potentiation of hippocampal neurons by binding to GRIA2/GluA2 mRNA, thereby inhibiting its translation (By similarity). Regulates proliferation of adult neural stem cells by binding to CDKN1A mRNA and promoting its expression (By similarity). Acts as a regulator of sleep and synaptic homeostasis by regulating translation of transcripts in neurons (By similarity). Required for embryonic and postnatal development of muscle tissue by undergoing liquid-liquid phase separation to assemble target mRNAs into cytoplasmic ribonucleoprotein granules (PubMed:30770808). Involved in the nuclear pore complex localization to the nuclear envelope by preventing cytoplasmic aggregation of nucleoporins: acts by preventing ectopic phase separation of nucleoporins in the cytoplasm via a microtubule-dependent mechanism (PubMed:32706158). Plays a role in the stabilization of PKP2 mRNA and therefore protein abundance, via its interaction with PKP3 (PubMed:25225333). May also do the same for PKP2, PKP3 and DSP via its interaction with PKP1 (PubMed:25225333). Forms a cytoplasmic messenger ribonucleoprotein (mRNP) network by packaging long mRNAs, serving as a scaffold that recruits proteins and signaling molecules. This network facilitates signaling reactions by maintaining proximity between kinases and substrates, crucial for processes like actomyosin reorganization (PubMed:39106863)","subunit":"Homodimer (via CC domains); homodiremization is required for FXR1-network nucleation (PubMed:39106863). Interacts with FMR1 (PubMed:11157796, PubMed:7489725, PubMed:8668200). Interacts with FRX2 (PubMed:7489725). Interacts with TDRD3 (PubMed:18664458). Interacts with HABP4 (PubMed:21771594). Interacts with CYFIP2 but not with CYFIP1 (By similarity). Interacts with EIF4G3; promoting translation of target mRNAs (By similarity). Interacts with ELAVL1 (PubMed:30067974). Interacts with CEP63; inhibiting 'Lys-63'-linked ubiquitination (PubMed:35989368). Interacts with PKP3; the interaction facilitates the binding of PKP3 to PKP2 mRNA (PubMed:25225333). Interacts with PKP1; the interaction may facilitate the binding of PKP1 to PKP2, PKP3 and DSP mRNA (PubMed:25225333)\n(Microbial infection) Interacts with Sindbis virus non-structural protein 3 (via C-terminus); this interaction inhibits the formation of host stress granules on viral mRNAs and the nsp3-FXR1 complexes bind viral RNAs and probably orchestrate the assembly of viral replication complexes","family":"Belongs to the FMR1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17382880","20417602","25225333","30067974","30770808","32706158","34731628","35989368","36306353","39106863"],"location":"Cytoplasm, Cytoplasmic ribonucleoprotein granule；Cytoplasm, Stress granule；Cytoplasm；Cell projection, dendrite；Cell projection, dendritic spine；Cell projection, axon；Nucleus envelope；Postsynapse","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；核质运输；激酶/磷酸化信号；细胞骨架/纤毛；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：mRNA-binding protein that acts as a regulator of mRNAs translation and/or stability, and which is required for various processes, such as neurogenesis, muscle development and spermatogenesis (PubMed:17382880, PubMed:20417602, PubMed:30067974, PubMed:34731628, PubMed:35989368, PubMed:36306353).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；核质运输；激酶/磷酸化信号；细胞骨架/纤毛；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"}};
